script:
frappe.ui.form.on("Quotation Item", {
    custom_discounted(frm, cdt, cdn) {
        apply_custom_discounted_total(frm, cdt, cdn);
    },

    qty(frm, cdt, cdn) {
        apply_custom_discounted_total(frm, cdt, cdn);
    }
});

function apply_custom_discounted_total(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    let qty = flt(row.qty);
    let discounted_total = flt(row.custom_discounted);

    if (!discounted_total) {
        return;
    }

    if (!qty || qty <= 0) {
        frappe.msgprint("Please enter quantity first before setting Custom Discounted Total.");
        frappe.model.set_value(cdt, cdn, "custom_discounted", 0);
        return;
    }

    let new_rate = discounted_total / qty;

    // Prevent ERPNext discount fields from applying discount twice
    if (frappe.meta.has_field(cdt, "discount_percentage")) {
        frappe.model.set_value(cdt, cdn, "discount_percentage", 0);
    }

    if (frappe.meta.has_field(cdt, "discount_amount")) {
        frappe.model.set_value(cdt, cdn, "discount_amount", 0);
    }

    frappe.model.set_value(cdt, cdn, "rate", new_rate);
    frappe.model.set_value(cdt, cdn, "amount", discounted_total);

    frm.refresh_field("items");
}

frappe.ui.form.on('Pick List', {

    scan_input_1(frm) {

        let scanned = frm.doc.scan_input_1;

        if (!scanned) return;

        frm.set_value("scan_input_1", "");

        console.log("📦 Scanned:", scanned);

        let found = false;

        (frm.doc.locations || []).forEach(row => {

            if (!row.warehouse) return;

            // 🔥 FLEXIBLE MATCH
            if (row.warehouse.trim().toLowerCase() === scanned.trim().toLowerCase()) {

                let remaining = row.qty - (row.picked_qty || 0);

                if (remaining > 0) {
                    row.picked_qty = (row.picked_qty || 0) + remaining;
                    found = true;
                }
            }
        });

        frm.refresh_field("locations");

        if (found) {
            frappe.show_alert("✅ Warehouse picked successfully");
        } else {
            frappe.msgprint("❌ No matching warehouse in this Pick List");
        }
    }
});

frappe.ui.form.on("Pick List", {
    refresh(frm) {
        frm.set_df_property("current_scanned_item", "read_only", 1);
    },

    scan_item_qr: async function (frm) {
        const scanned_item = (frm.doc.scan_item_qr || "").trim();

        if (!scanned_item) return;

        await frm.set_value("scan_item_qr", "");

        const item_res = await frappe.db.get_value("Item", scanned_item, ["name", "item_name"]);

        if (!item_res.message || !item_res.message.name) {
            await frm.set_value("current_scanned_item", "");
            frappe.show_alert({
                message: __("Invalid Item Code QR: {0}", [scanned_item]),
                indicator: "red"
            });
            frappe.utils.play_sound("error");
            return;
        }

        const open_rows = (frm.doc.locations || []).filter(row => {
            return row.item_code === scanned_item
                && flt(row.picked_qty || 0) < flt(row.qty || 0);
        });

        if (!open_rows.length) {
            await frm.set_value("current_scanned_item", "");
            frappe.show_alert({
                message: __("Item {0} is not in this Pick List or is already fully picked.", [scanned_item]),
                indicator: "red"
            });
            frappe.utils.play_sound("error");
            return;
        }

        await frm.set_value("current_scanned_item", scanned_item);

        frappe.show_alert({
            message: __("Item verified: {0}. Now scan the Batch QR.", [scanned_item]),
            indicator: "green"
        });

        frappe.utils.play_sound("submit");
    },

    scan_batch_qr: async function (frm) {
        const scanned_batch = (frm.doc.scan_batch_qr || "").trim();
        const scanned_item = frm.doc.current_scanned_item;

        if (!scanned_batch) return;

        await frm.set_value("scan_batch_qr", "");

        if (!scanned_item) {
            frappe.show_alert({
                message: __("Please scan the Item QR first before scanning the Batch QR."),
                indicator: "red"
            });
            frappe.utils.play_sound("error");
            return;
        }

        const batch_res = await frappe.db.get_value("Batch", scanned_batch, [
            "name",
            "item",
            "disabled",
            "expiry_date"
        ]);

        if (!batch_res.message || !batch_res.message.name) {
            frappe.show_alert({
                message: __("Invalid Batch QR: {0}", [scanned_batch]),
                indicator: "red"
            });
            frappe.utils.play_sound("error");
            return;
        }

        const batch = batch_res.message;

        if (cint(batch.disabled)) {
            frappe.show_alert({
                message: __("Batch {0} is disabled.", [scanned_batch]),
                indicator: "red"
            });
            frappe.utils.play_sound("error");
            return;
        }

        if (batch.item !== scanned_item) {
            frappe.show_alert({
                message: __("Wrong batch. Batch {0} belongs to Item {1}, not scanned Item {2}.", [
                    scanned_batch,
                    batch.item,
                    scanned_item
                ]),
                indicator: "red"
            });
            frappe.utils.play_sound("error");
            return;
        }

        const matching_row = (frm.doc.locations || []).find(row => {
            const item_matches = row.item_code === scanned_item;
            const batch_matches = !row.batch_no || row.batch_no === scanned_batch;
            const qty_open = flt(row.picked_qty || 0) < flt(row.qty || 0);

            return item_matches && batch_matches && qty_open;
        });

        if (!matching_row) {
            frappe.show_alert({
                message: __("No open Pick List row found for Item {0} and Batch {1}.", [
                    scanned_item,
                    scanned_batch
                ]),
                indicator: "red"
            });
            frappe.utils.play_sound("error");
            return;
        }

        const required_qty = flt(matching_row.qty || 0);
        const current_picked_qty = flt(matching_row.picked_qty || 0);
        const remaining_qty = required_qty - current_picked_qty;

        if (remaining_qty <= 0) {
            frappe.show_alert({
                message: __("Item {0} is already fully picked.", [scanned_item]),
                indicator: "red"
            });
            frappe.utils.play_sound("error");
            return;
        }

        frappe.prompt(
            [
                {
                    label: __("Qty to Pick"),
                    fieldname: "qty_to_pick",
                    fieldtype: "Float",
                    reqd: 1,
                    default: 1
                }
            ],
            async function (values) {
                const qty_to_add = flt(values.qty_to_pick || 0);

                if (qty_to_add <= 0) {
                    frappe.show_alert({
                        message: __("Qty must be greater than zero."),
                        indicator: "red"
                    });
                    frappe.utils.play_sound("error");
                    return;
                }

                if (qty_to_add > remaining_qty) {
                    frappe.show_alert({
                        message: __("You can only pick {0} more piece(s) for Item {1}.", [
                            remaining_qty,
                            scanned_item
                        ]),
                        indicator: "red"
                    });
                    frappe.utils.play_sound("error");
                    return;
                }

                const new_picked_qty = current_picked_qty + qty_to_add;

                await frappe.model.set_value(
                    matching_row.doctype,
                    matching_row.name,
                    "batch_no",
                    scanned_batch
                );

                await frappe.model.set_value(
                    matching_row.doctype,
                    matching_row.name,
                    "picked_qty",
                    new_picked_qty
                );

                frm.refresh_field("locations");

                frappe.show_alert({
                    message: __("Batch verified: {0}. Picked Qty updated: {1} / {2}", [
                        scanned_batch,
                        new_picked_qty,
                        required_qty
                    ]),
                    indicator: "green"
                });

                frappe.utils.play_sound("submit");

                await frm.set_value("current_scanned_item", "");
            },
            __("Enter Pick Quantity"),
            __("Update Picked Qty")
        );
    }
});

frappe.ui.form.on("Pick List", {
    setup(frm) {
        setup_central_fulfillment_queries(frm);
    },

    onload(frm) {
        load_pick_list_fulfillment_information(frm);
    },

    refresh(frm) {
        // Existing scanner logic
        setup_pick_qty_scanner(frm);
        focus_pick_qty_scanner(frm);

        // Central fulfillment logic
        load_pick_list_fulfillment_information(frm);
        show_pick_list_fulfillment_banner(frm);
    },

    pick_qty_scanner(frm) {
        const scanned_batch = clean_scan_value(
            frm.doc.pick_qty_scanner
        );

        if (!scanned_batch) {
            return;
        }

        process_scanned_batch(frm, scanned_batch);
    },

    validate(frm) {
        validate_pick_list_fulfillment(frm);
    }
});


frappe.ui.form.on("Pick List Item", {
    locations_add(frm) {
        load_pick_list_fulfillment_information(frm);
    },

    sales_order(frm) {
        load_pick_list_fulfillment_information(frm);
    },

    warehouse(frm, cdt, cdn) {
        validate_selected_location_warehouse(
            frm,
            cdt,
            cdn
        );
    }
});


/* =========================================================
   CENTRAL FULFILLMENT LOGIC
   ========================================================= */

function setup_central_fulfillment_queries(frm) {
    if (frm.fields_dict.custom_branch) {
        frm.set_query("custom_branch", function () {
            return {
                filters: {
                    disabled: 0
                }
            };
        });
    }

    if (frm.fields_dict.custom_fulfillment_warehouse) {
        frm.set_query(
            "custom_fulfillment_warehouse",
            function () {
                const filters = {};

                if (frm.doc.company) {
                    filters.company = frm.doc.company;
                }

                return {
                    filters: filters
                };
            }
        );
    }
}


async function load_pick_list_fulfillment_information(frm) {
    if (frm._loading_central_fulfillment) {
        return;
    }

    const sales_orders = get_pick_list_sales_orders(frm);

    if (!sales_orders.length) {
        return;
    }

    frm._loading_central_fulfillment = true;

    try {
        let selected_branch = "";
        let selected_fulfillment_warehouse = "";
        let centralized_order_found = false;

        for (const sales_order of sales_orders) {
            const response = await frappe.db.get_value(
                "Sales Order",
                sales_order,
                [
                    "company",
                    "branch",
                    "custom_fulfillment_warehouse",
                    "custom_central_fulfillment"
                ]
            );

            const values =
                response && response.message
                    ? response.message
                    : {};

            if (!cint(values.custom_central_fulfillment)) {
                continue;
            }

            centralized_order_found = true;

            if (
                values.company &&
                frm.doc.company &&
                values.company !== frm.doc.company
            ) {
                frappe.throw(
                    __(
                        "Sales Order {0} belongs to company {1}, but this Pick List belongs to company {2}.",
                        [
                            sales_order,
                            values.company,
                            frm.doc.company
                        ]
                    )
                );
            }

            if (!values.branch) {
                frappe.throw(
                    __(
                        "Branch is missing from Sales Order {0}.",
                        [sales_order]
                    )
                );
            }

            if (!values.custom_fulfillment_warehouse) {
                frappe.throw(
                    __(
                        "Fulfillment Warehouse is missing from Sales Order {0}.",
                        [sales_order]
                    )
                );
            }

            if (!selected_branch) {
                selected_branch = values.branch;
            } else if (selected_branch !== values.branch) {
                frappe.throw(
                    __(
                        "This Pick List contains centralized Sales Orders from different branches. Create a separate Pick List for each branch."
                    )
                );
            }

            if (!selected_fulfillment_warehouse) {
                selected_fulfillment_warehouse =
                    values.custom_fulfillment_warehouse;
            } else if (
                selected_fulfillment_warehouse !==
                values.custom_fulfillment_warehouse
            ) {
                frappe.throw(
                    __(
                        "This Pick List contains Sales Orders with different fulfillment warehouses."
                    )
                );
            }
        }

        if (!centralized_order_found) {
            return;
        }

        frm.__central_fulfillment_enabled = true;
        frm.__central_fulfillment_branch = selected_branch;
        frm.__central_fulfillment_warehouse =
            selected_fulfillment_warehouse;

        if (
            frm.fields_dict.custom_branch &&
            frm.doc.custom_branch !== selected_branch
        ) {
            await frm.set_value(
                "custom_branch",
                selected_branch
            );
        }

        if (
            frm.fields_dict.custom_fulfillment_warehouse &&
            frm.doc.custom_fulfillment_warehouse !==
                selected_fulfillment_warehouse
        ) {
            await frm.set_value(
                "custom_fulfillment_warehouse",
                selected_fulfillment_warehouse
            );
        }

        await validate_all_location_warehouses(frm);

        show_pick_list_fulfillment_banner(frm);

    } catch (error) {
        console.error(
            "Central fulfillment loading failed:",
            error
        );

        throw error;

    } finally {
        frm._loading_central_fulfillment = false;
    }
}


function get_pick_list_sales_orders(frm) {
    const sales_orders = [];

    (frm.doc.locations || []).forEach(function (row) {
        const sales_order = clean_scan_value(
            row.sales_order
        );

        if (
            sales_order &&
            !sales_orders.includes(sales_order)
        ) {
            sales_orders.push(sales_order);
        }
    });

    return sales_orders;
}


async function validate_pick_list_fulfillment(frm) {
    const sales_orders = get_pick_list_sales_orders(frm);

    if (!sales_orders.length) {
        return;
    }

    await load_pick_list_fulfillment_information(frm);

    if (!frm.__central_fulfillment_enabled) {
        return;
    }

    if (!frm.doc.custom_branch) {
        frappe.throw(
            __(
                "Branch is required for a centralized fulfillment Pick List."
            )
        );
    }

    if (!frm.doc.custom_fulfillment_warehouse) {
        frappe.throw(
            __(
                "Fulfillment Warehouse is required for a centralized fulfillment Pick List."
            )
        );
    }

    const missing_warehouse_rows = [];

    (frm.doc.locations || []).forEach(function (row) {
        if (!row.warehouse) {
            missing_warehouse_rows.push(row.idx);
        }
    });

    if (missing_warehouse_rows.length) {
        frappe.throw(
            __(
                "Warehouse is missing on Pick List row(s): {0}.",
                [missing_warehouse_rows.join(", ")]
            )
        );
    }

    await validate_all_location_warehouses(frm);
}


async function validate_all_location_warehouses(frm) {
    const fulfillment_warehouse =
        frm.doc.custom_fulfillment_warehouse ||
        frm.__central_fulfillment_warehouse;

    if (!fulfillment_warehouse) {
        return;
    }

    const root_response = await frappe.db.get_value(
        "Warehouse",
        fulfillment_warehouse,
        [
            "name",
            "company",
            "is_group",
            "lft",
            "rgt"
        ]
    );

    const root =
        root_response && root_response.message
            ? root_response.message
            : {};

    if (!root.name) {
        frappe.throw(
            __(
                "Fulfillment Warehouse {0} could not be found.",
                [fulfillment_warehouse]
            )
        );
    }

    if (
        root.company &&
        frm.doc.company &&
        root.company !== frm.doc.company
    ) {
        frappe.throw(
            __(
                "Fulfillment Warehouse {0} belongs to company {1}, but this Pick List belongs to company {2}.",
                [
                    fulfillment_warehouse,
                    root.company,
                    frm.doc.company
                ]
            )
        );
    }

    for (const row of frm.doc.locations || []) {
        if (!row.warehouse) {
            continue;
        }

        await validate_location_against_root(
            frm,
            row,
            root
        );
    }
}


async function validate_selected_location_warehouse(
    frm,
    cdt,
    cdn
) {
    if (
        frm._validating_location_warehouse ||
        !frm.__central_fulfillment_enabled
    ) {
        return;
    }

    const row = locals[cdt][cdn];

    if (!row || !row.warehouse) {
        return;
    }

    const fulfillment_warehouse =
        frm.doc.custom_fulfillment_warehouse ||
        frm.__central_fulfillment_warehouse;

    if (!fulfillment_warehouse) {
        return;
    }

    frm._validating_location_warehouse = true;

    try {
        const root_response = await frappe.db.get_value(
            "Warehouse",
            fulfillment_warehouse,
            [
                "name",
                "company",
                "lft",
                "rgt"
            ]
        );

        const root =
            root_response && root_response.message
                ? root_response.message
                : {};

        if (!root.name) {
            return;
        }

        await validate_location_against_root(
            frm,
            row,
            root
        );

    } catch (error) {
        console.error(error);

        await frappe.model.set_value(
            cdt,
            cdn,
            "warehouse",
            ""
        );

    } finally {
        frm._validating_location_warehouse = false;
    }
}


async function validate_location_against_root(
    frm,
    row,
    root
) {
    const warehouse_response =
        await frappe.db.get_value(
            "Warehouse",
            row.warehouse,
            [
                "name",
                "company",
                "is_group",
                "lft",
                "rgt"
            ]
        );

    const warehouse =
        warehouse_response &&
        warehouse_response.message
            ? warehouse_response.message
            : {};

    if (!warehouse.name) {
        frappe.throw(
            __(
                "Row {0}: Warehouse {1} could not be found.",
                [
                    row.idx,
                    row.warehouse
                ]
            )
        );
    }

    if (
        warehouse.company &&
        frm.doc.company &&
        warehouse.company !== frm.doc.company
    ) {
        frappe.throw(
            __(
                "Row {0}: Warehouse {1} belongs to company {2}, not company {3}.",
                [
                    row.idx,
                    row.warehouse,
                    warehouse.company,
                    frm.doc.company
                ]
            )
        );
    }

    if (cint(warehouse.is_group)) {
        frappe.throw(
            __(
                "Row {0}: Group warehouse {1} cannot be used for picking. Select an actual child or bin warehouse.",
                [
                    row.idx,
                    row.warehouse
                ]
            )
        );
    }

    const is_under_fulfillment_warehouse =
        flt(warehouse.lft) >= flt(root.lft) &&
        flt(warehouse.rgt) <= flt(root.rgt);

    if (!is_under_fulfillment_warehouse) {
        frappe.throw(
            __(
                "Row {0}: Warehouse {1} is outside the configured fulfillment warehouse {2}.",
                [
                    row.idx,
                    row.warehouse,
                    root.name
                ]
            )
        );
    }
}


function show_pick_list_fulfillment_banner(frm) {
    const branch =
        frm.doc.custom_branch ||
        frm.__central_fulfillment_branch;

    const fulfillment_warehouse =
        frm.doc.custom_fulfillment_warehouse ||
        frm.__central_fulfillment_warehouse;

    if (!branch || !fulfillment_warehouse) {
        return;
    }

    const banner_key =
        `${branch}::${fulfillment_warehouse}`;

    if (
        frm.__last_fulfillment_banner ===
        banner_key
    ) {
        return;
    }

    frm.__last_fulfillment_banner =
        banner_key;

    frm.dashboard.add_comment(
        __(
            "Selling Branch: <b>{0}</b><br>" +
            "Fulfillment Warehouse: <b>{1}</b><br>" +
            "Picking must use an actual child or bin warehouse under the configured fulfillment warehouse.",
            [
                frappe.utils.escape_html(branch),
                frappe.utils.escape_html(
                    fulfillment_warehouse
                )
            ]
        ),
        "blue",
        true
    );
}


/* =========================================================
   EXISTING PICK QUANTITY SCANNER LOGIC
   ========================================================= */

function setup_pick_qty_scanner(frm) {
    if (
        !frm.fields_dict.pick_qty_scanner ||
        !frm.fields_dict.pick_qty_scanner.$input
    ) {
        return;
    }

    const $input =
        frm.fields_dict.pick_qty_scanner.$input;

    $input.attr(
        "placeholder",
        "Scan Batch No QR here"
    );

    // Prevent duplicate event bindings after refresh.
    $input.off("keydown.pick_qty_scanner");
    $input.off("input.pick_qty_scanner");

    $input.on(
        "keydown.pick_qty_scanner",
        function (e) {
            if (
                e.key === "Enter" ||
                e.which === 13
            ) {
                e.preventDefault();

                const scanned_batch =
                    clean_scan_value(
                        $input.val()
                    );

                if (scanned_batch) {
                    process_scanned_batch(
                        frm,
                        scanned_batch
                    );
                }
            }
        }
    );

    let scan_timer = null;

    $input.on(
        "input.pick_qty_scanner",
        function () {
            clearTimeout(scan_timer);

            scan_timer = setTimeout(
                function () {
                    const scanned_batch =
                        clean_scan_value(
                            $input.val()
                        );

                    if (scanned_batch) {
                        process_scanned_batch(
                            frm,
                            scanned_batch
                        );
                    }
                },
                500
            );
        }
    );
}


async function process_scanned_batch(
    frm,
    scanned_batch
) {
    scanned_batch =
        clean_scan_value(scanned_batch);

    if (!scanned_batch) {
        return;
    }

    if (frm._processing_pick_scan) {
        return;
    }

    frm._processing_pick_scan = true;

    try {
        await frm.set_value(
            "pick_qty_scanner",
            ""
        );

        set_scan_status_only(
            frm,
            `Checking Batch No: ${scanned_batch}`
        );

        const batch_res =
            await frappe.db.get_value(
                "Batch",
                scanned_batch,
                [
                    "name",
                    "item",
                    "disabled"
                ]
            );

        if (
            !batch_res.message ||
            !batch_res.message.name
        ) {
            show_scan_error(
                frm,
                `Invalid Batch No: ${scanned_batch}`
            );

            release_scanner_lock(frm);
            return;
        }

        const batch = batch_res.message;

        const batch_item =
            clean_scan_value(batch.item);

        if (cint(batch.disabled)) {
            show_scan_error(
                frm,
                `Batch ${scanned_batch} is disabled.`
            );

            release_scanner_lock(frm);
            return;
        }

        if (!batch_item) {
            show_scan_error(
                frm,
                `Batch ${scanned_batch} has no linked Item Code.`
            );

            release_scanner_lock(frm);
            return;
        }

        const matching_rows =
            (frm.doc.locations || []).filter(
                function (row) {
                    const row_batch =
                        clean_scan_value(
                            row.batch_no
                        );

                    const row_item =
                        clean_scan_value(
                            row.item_code
                        );

                    const item_matches =
                        row_item === batch_item;

                    const batch_matches =
                        row_batch === scanned_batch;

                    const qty_open =
                        flt(row.picked_qty || 0) <
                        flt(row.qty || 0);

                    return (
                        item_matches &&
                        batch_matches &&
                        qty_open
                    );
                }
            );

        if (!matching_rows.length) {
            show_scan_error(
                frm,
                `No open Pick List row found for Batch ${scanned_batch} / Item ${batch_item}.`
            );

            console.log(
                "Scanned Batch:",
                scanned_batch
            );

            console.log(
                "Batch Item:",
                batch_item
            );

            console.table(
                (frm.doc.locations || []).map(
                    function (row) {
                        return {
                            row: row.idx,
                            item_code: row.item_code,
                            batch_no: row.batch_no,
                            warehouse: row.warehouse,
                            qty: row.qty,
                            picked_qty:
                                row.picked_qty
                        };
                    }
                )
            );

            release_scanner_lock(frm);
            return;
        }

        if (matching_rows.length === 1) {
            open_qty_dialog(
                frm,
                matching_rows[0],
                batch_item,
                scanned_batch
            );

            return;
        }

        open_row_selection_dialog(
            frm,
            matching_rows,
            batch_item,
            scanned_batch
        );

    } catch (error) {
        console.error(error);

        show_scan_error(
            frm,
            "Scan failed. Please check the browser console."
        );

        release_scanner_lock(frm);
    }
}


function open_row_selection_dialog(
    frm,
    matching_rows,
    item_code,
    batch_no
) {
    const options = matching_rows.map(
        function (row) {
            const required_qty =
                flt(row.qty || 0);

            const picked_qty =
                flt(row.picked_qty || 0);

            const remaining_qty =
                required_qty - picked_qty;

            return {
                label:
                    `Row ${row.idx}` +
                    ` | Item: ${row.item_code}` +
                    ` | Batch: ${row.batch_no}` +
                    ` | Warehouse: ${row.warehouse || ""}` +
                    ` | Remaining: ${remaining_qty}`,

                value: row.name
            };
        }
    );

    const dialog = new frappe.ui.Dialog({
        title: "Multiple Rows Found",

        fields: [
            {
                label: "Select Pick List Row",
                fieldname: "row_name",
                fieldtype: "Select",
                options: options,
                reqd: 1
            }
        ],

        primary_action_label: "Continue",

        primary_action(values) {
            const selected_row =
                matching_rows.find(
                    function (row) {
                        return (
                            row.name ===
                            values.row_name
                        );
                    }
                );

            if (!selected_row) {
                show_scan_error(
                    frm,
                    "Selected row was not found."
                );

                dialog.hide();
                release_scanner_lock(frm);
                return;
            }

            dialog.hide();

            open_qty_dialog(
                frm,
                selected_row,
                item_code,
                batch_no
            );
        }
    });

    dialog.show();

    dialog.$wrapper.on(
        "hidden.bs.modal",
        function () {
            if (frm._processing_pick_scan) {
                release_scanner_lock(frm);
            }
        }
    );
}


function open_qty_dialog(
    frm,
    row,
    item_code,
    batch_no
) {
    const required_qty =
        flt(row.qty || 0);

    const current_picked_qty =
        flt(row.picked_qty || 0);

    const remaining_qty =
        required_qty -
        current_picked_qty;

    if (remaining_qty <= 0) {
        show_scan_error(
            frm,
            `Item ${item_code} / Batch ${batch_no} is already fully picked.`
        );

        release_scanner_lock(frm);
        return;
    }

    set_scan_status_only(
        frm,
        `Matched Row ${row.idx}: ` +
        `Item ${item_code}, ` +
        `Batch ${batch_no}, ` +
        `Warehouse ${row.warehouse || ""}, ` +
        `Remaining ${remaining_qty}`
    );

    const dialog = new frappe.ui.Dialog({
        title: "Enter Qty to Pick",

        fields: [
            {
                label:
                    `Qty to Pick | Remaining Needed: ${remaining_qty}`,

                fieldname: "qty_to_pick",
                fieldtype: "Float",
                reqd: 1,
                default: 1
            }
        ],

        primary_action_label:
            "Update Picked Qty",

        primary_action:
            async function (values) {
                const qty_to_pick =
                    flt(
                        values.qty_to_pick ||
                        0
                    );

                if (qty_to_pick <= 0) {
                    frappe.msgprint(
                        "Qty to pick must be greater than zero."
                    );

                    frappe.utils.play_sound(
                        "error"
                    );

                    return;
                }

                if (
                    qty_to_pick >
                    remaining_qty
                ) {
                    frappe.msgprint(
                        `Rejected. You only need ${remaining_qty} more piece(s) for Item ${item_code}, Batch ${batch_no}.`
                    );

                    frappe.utils.play_sound(
                        "error"
                    );

                    return;
                }

                const new_picked_qty =
                    current_picked_qty +
                    qty_to_pick;

                await frappe.model.set_value(
                    row.doctype,
                    row.name,
                    "picked_qty",
                    new_picked_qty
                );

                frm.refresh_field(
                    "locations"
                );

                show_scan_success(
                    frm,
                    `Accepted. Row ${row.idx}: ` +
                    `Item ${item_code}, ` +
                    `Batch ${batch_no}. ` +
                    `Picked ${qty_to_pick}. ` +
                    `Total picked ${new_picked_qty} / ${required_qty}.`
                );

                dialog.hide();
                release_scanner_lock(frm);
            }
    });

    dialog.show();

    setTimeout(
        function () {
            const qty_input =
                dialog.fields_dict.qty_to_pick;

            if (
                qty_input &&
                qty_input.$input
            ) {
                qty_input.$input.focus();
                qty_input.$input.select();
            }
        },
        300
    );

    dialog.$wrapper.on(
        "hidden.bs.modal",
        function () {
            if (frm._processing_pick_scan) {
                release_scanner_lock(frm);
            }
        }
    );
}


function release_scanner_lock(frm) {
    setTimeout(
        function () {
            frm._processing_pick_scan =
                false;

            focus_pick_qty_scanner(frm);
        },
        300
    );
}


