function show_quotation_special_approval_warning(frm) {
    if (!frm || !frm.doc) {
        return;
    }

    frm.dashboard.clear_headline();

    let requires_special_approval = false;
    let has_valid_item = false;

    (frm.doc.items || []).forEach(function(row) {
        if (!row.item_code) {
            return;
        }

        has_valid_item = true;

        let qty = flt(row.qty);
        let rate = flt(row.rate);
        let amount = flt(row.amount);

        let custom_marked_up_rate = flt(row.custom_marked_up_rate);

        let discount_percentage = flt(row.discount_percentage);
        let discount_amount = flt(row.discount_amount);
        let custom_discount = flt(row.custom_discount);
        let custom_discounted = flt(row.custom_discounted);

        let original_marked_up_total = custom_marked_up_rate * qty;

        /*
            Warning-only logic.
            This script does not update frm.doc or child row values.
            Server Script is still the final authority for workflow routing.
        */

        if (rate === 0 && custom_marked_up_rate > 0) {
            requires_special_approval = true;
        }

        if (discount_percentage > 0) {
            requires_special_approval = true;
        }

        if (discount_amount > 0) {
            requires_special_approval = true;
        }

        if (custom_discount > 0) {
            requires_special_approval = true;
        }

        if (
            custom_discounted > 0 &&
            original_marked_up_total > 0 &&
            custom_discounted < original_marked_up_total
        ) {
            requires_special_approval = true;
        }

        if (
            amount > 0 &&
            original_marked_up_total > 0 &&
            amount < original_marked_up_total
        ) {
            requires_special_approval = true;
        }
    });

    /*
        Bottom-form additional discount check.
        This catches discounts added below the item table.
    */

    if (flt(frm.doc.additional_discount_percentage) > 0) {
        requires_special_approval = true;
    }

    if (flt(frm.doc.discount_amount) > 0) {
        requires_special_approval = true;
    }

    if (!has_valid_item) {
        return;
    }

    if (requires_special_approval) {
        frm.dashboard.set_headline_alert(
            'This quotation requires approval to higher management because a discount is detected. Please continue for the approval process.',
            'orange'
        );
    }
}

// ============================================================
// QUOTATION - BRANCH MARKUP AND FULFILLMENT
// MERGE-SAFE FULL CLIENT SCRIPT
// ERPNext / Frappe v16
// ============================================================
//
// PRESERVED:
// ------------------------------------------------------------
// 1. Branch markup from Branch Markup Setting.
// 2. custom_base_rate_before_markup.
// 3. custom_branch_markup_percentage.
// 4. custom_marked_up_rate.
// 5. custom_discounted as TOTAL row amount.
// 6. ERPNext rate remains per-unit final rate.
// 7. Warehouse assignment.
// 8. Selling Cost Center assignment.
// 9. Central fulfillment validation.
// 10. Company validation.
// 11. One reusable fulfillment flag.
// 12. Branch Fulfillment = GREEN.
// 13. Central Fulfillment = BLUE.
// 14. Flag updates when fulfillment changes.
// 15. Flag updates when Branch changes.
// 16. No duplicate fulfillment flags.
//
// NEW:
// ------------------------------------------------------------
// 17. Company comes from Sales Access Hierarchy.
// 18. Branch comes from same Sales Access Hierarchy record.
// 19. Company is applied BEFORE Branch.
// 20. One API call for Company + Branch.
// 21. Existing values are never overwritten automatically.
// ============================================================


// ============================================================
// FIELD CONFIGURATION
// ============================================================

const COMPANY_FIELD =
    "company";

const BRANCH_FIELD =
    "custom_branch";

const CENTRAL_FULFILLMENT_FIELD =
    "custom_central_fulfillment";

const SELECTED_WAREHOUSE_FIELD =
    "custom_fulfillment_warehouse";

const BRANCH_DEFAULT_WAREHOUSE_FIELD =
    "custom_default_branch_warehouse";

const BRANCH_CENTRAL_WAREHOUSE_FIELD =
    "custom_fulfillment_warehouse";

const BRANCH_COST_CENTER_FIELD =
    "custom_selling_cost_center";

const BRANCH_ALLOW_CENTRAL_FIELD =
    "custom_allow_central_fulfillment";

const BRANCH_WAREHOUSE_COMPANY_FIELD =
    "custom_warehouse_company";


// ============================================================
// PRICING FIELD CONFIGURATION
// ============================================================

const BASE_RATE_FIELD =
    "custom_base_rate_before_markup";

const MARKUP_PERCENT_FIELD =
    "custom_branch_markup_percentage";

const MARKED_UP_RATE_FIELD =
    "custom_marked_up_rate";

const TOTAL_DISCOUNTED_FIELD =
    "custom_discounted";


// ============================================================
// FULFILLMENT FLAG CONFIGURATION
// ============================================================

const QUOTATION_FULFILLMENT_FLAG_CLASS =
    "custom-quotation-fulfillment-flag";


// ============================================================
// QUOTATION EVENTS
// ============================================================

frappe.ui.form.on("Quotation", {

    setup(frm) {

        setup_quotation_queries(frm);

        setup_branch_markup_flags(frm);

        setup_quotation_fulfillment_flags(frm);
    },


    // ========================================================
    // ONLOAD
    // ========================================================

    async onload(frm) {

        setup_branch_markup_flags(frm);

        setup_quotation_fulfillment_flags(frm);


        // ----------------------------------------------------
        // DEFAULT COMPANY + BRANCH
        //
        // IMPORTANT:
        // Company is set before Branch.
        // ----------------------------------------------------

        if (
            frm.is_new() &&
            (
                !frm.doc[COMPANY_FIELD] ||
                !frm.doc[BRANCH_FIELD]
            )
        ) {
            await set_sales_defaults_from_hierarchy(
                frm
            );
        }


        // ----------------------------------------------------
        // LOAD BRANCH SETTINGS
        // ----------------------------------------------------

        if (
            frm.doc[BRANCH_FIELD]
        ) {

            await load_branch_markup(
                frm
            );

            await apply_quotation_fulfillment_settings(
                frm,
                false
            );

            update_quotation_fulfillment_flag(
                frm
            );
        }
    },


    // ========================================================
    // REFRESH
    // ========================================================

    async refresh(frm) {

        setup_branch_markup_flags(frm);

        setup_quotation_fulfillment_flags(frm);


        // ----------------------------------------------------
        // DEFAULT COMPANY + BRANCH
        // ----------------------------------------------------

        if (
            frm.is_new() &&
            (
                !frm.doc[COMPANY_FIELD] ||
                !frm.doc[BRANCH_FIELD]
            )
        ) {
            await set_sales_defaults_from_hierarchy(
                frm
            );
        }


        // ----------------------------------------------------
        // REFRESH FULFILLMENT SETTINGS
        // ----------------------------------------------------

        if (
            frm.doc[BRANCH_FIELD]
        ) {

            await apply_quotation_fulfillment_settings(
                frm,
                false
            );

            update_quotation_fulfillment_flag(
                frm
            );

        } else {

            remove_quotation_fulfillment_flag(
                frm
            );
        }
    },


    // ========================================================
    // BRANCH CHANGED
    // ========================================================

    async custom_branch(frm) {

        setup_branch_markup_flags(frm);

        setup_quotation_fulfillment_flags(frm);


        // ----------------------------------------------------
        // RESET BRANCH-DEPENDENT STATE
        // ----------------------------------------------------

        frm._branch_markup_percentage =
            0;

        frm.__branch_cost_center =
            "";

        frm.__selected_order_warehouse =
            "";

        frm.__branch_fulfillment_settings =
            null;


        // ----------------------------------------------------
        // BRANCH CLEARED
        // ----------------------------------------------------

        if (
            !frm.doc[BRANCH_FIELD]
        ) {

            await clear_quotation_fulfillment_fields(
                frm
            );

            clear_all_markup_fields(
                frm
            );

            remove_quotation_fulfillment_flag(
                frm
            );

            return;
        }


        // ----------------------------------------------------
        // LOAD MARKUP
        // ----------------------------------------------------

        await load_branch_markup(
            frm
        );


        // ----------------------------------------------------
        // LOAD FULFILLMENT
        // ----------------------------------------------------

        await apply_quotation_fulfillment_settings(
            frm,
            true
        );


        // ----------------------------------------------------
        // RECALCULATE PRICES
        // ----------------------------------------------------

        recalculate_all_items(
            frm
        );


        // ----------------------------------------------------
        // UPDATE FLAG
        // ----------------------------------------------------

        update_quotation_fulfillment_flag(
            frm
        );
    },


    // ========================================================
    // CENTRAL FULFILLMENT CHECKBOX
    // ========================================================

    async custom_central_fulfillment(frm) {

        if (
            !frm.doc[BRANCH_FIELD]
        ) {

            frappe.msgprint(
                __(
                    "Select a Branch before changing the fulfillment mode."
                )
            );

            await frm.set_value(
                CENTRAL_FULFILLMENT_FIELD,
                0
            );

            remove_quotation_fulfillment_flag(
                frm
            );

            return;
        }


        // ----------------------------------------------------
        // SWITCH WAREHOUSE
        // ----------------------------------------------------

        await apply_quotation_fulfillment_settings(
            frm,
            true
        );


        // ----------------------------------------------------
        // RECALCULATE ITEMS
        // ----------------------------------------------------

        recalculate_all_items(
            frm
        );


        // ----------------------------------------------------
        // UPDATE FLAG
        // ----------------------------------------------------

        update_quotation_fulfillment_flag(
            frm
        );
    },


    // ========================================================
    // COMPANY CHANGED
    // ========================================================

    async company(frm) {

        if (
            !frm.doc[BRANCH_FIELD]
        ) {

            remove_quotation_fulfillment_flag(
                frm
            );

            return;
        }


        await apply_quotation_fulfillment_settings(
            frm,
            false
        );

        update_quotation_fulfillment_flag(
            frm
        );
    },


    // ========================================================
    // VALIDATE
    // ========================================================

    async validate(frm) {

        if (
            frm.doc[BRANCH_FIELD]
        ) {

            await apply_quotation_fulfillment_settings(
                frm,
                false
            );
        }


        validate_quotation_fulfillment(
            frm
        );


        recalculate_all_items(
            frm
        );


        update_quotation_fulfillment_flag(
            frm
        );
    },


    // ========================================================
    // BEFORE WORKFLOW ACTION
    // ========================================================

    async before_workflow_action(frm) {

        if (
            frm.doc[BRANCH_FIELD]
        ) {

            await apply_quotation_fulfillment_settings(
                frm,
                false
            );
        }


        validate_quotation_fulfillment(
            frm
        );


        recalculate_all_items(
            frm
        );


        update_quotation_fulfillment_flag(
            frm
        );
    },


    // ========================================================
    // ITEM ADDED
    // ========================================================

    items_add(frm, cdt, cdn) {

        setTimeout(
            async function () {

                await apply_item_fulfillment_settings(
                    frm,
                    cdt,
                    cdn
                );

                recalculate_single_item(
                    frm,
                    cdt,
                    cdn
                );

            },
            300
        );
    }
});


