// QUOTATION ITEM EVENTS
// ============================================================

frappe.ui.form.on("Quotation Item", {

    // ========================================================
    // ITEM CODE
    // ========================================================

    async item_code(
        frm,
        cdt,
        cdn
    ) {

        clear_row_markup_values(
            cdt,
            cdn
        );


        await apply_item_fulfillment_settings(
            frm,
            cdt,
            cdn
        );


        recalculate_single_item(
            frm,
            cdt,
            cdn
        );


        // ERPNext may populate defaults after item_code.

        setTimeout(
            async function () {

                await apply_item_fulfillment_settings(
                    frm,
                    cdt,
                    cdn
                );

                recalculate_single_item(
                    frm,
                    cdt,
                    cdn
                );

            },
            300
        );


        setTimeout(
            async function () {

                await apply_item_fulfillment_settings(
                    frm,
                    cdt,
                    cdn
                );

                recalculate_single_item(
                    frm,
                    cdt,
                    cdn
                );

            },
            800
        );
    },


    // ========================================================
    // PRICE LIST RATE
    // ========================================================

    price_list_rate(
        frm,
        cdt,
        cdn
    ) {

        recalculate_single_item(
            frm,
            cdt,
            cdn
        );
    },


    // ========================================================
    // RATE
    // ========================================================

    rate(
        frm,
        cdt,
        cdn
    ) {

        if (
            frm._applying_branch_markup
        ) {
            return;
        }


        const row =
            locals[cdt][cdn];


        if (
            row &&
            !flt(
                row[
                    BASE_RATE_FIELD
                ]
            ) &&
            flt(row.rate)
        ) {

            frappe.model.set_value(
                cdt,
                cdn,
                BASE_RATE_FIELD,
                flt(row.rate)
            );
        }


        recalculate_single_item(
            frm,
            cdt,
            cdn
        );
    },


    // ========================================================
    // QTY
    // ========================================================

    qty(
        frm,
        cdt,
        cdn
    ) {

        recalculate_single_item(
            frm,
            cdt,
            cdn
        );
    },


    // ========================================================
    // CUSTOM DISCOUNTED
    // ========================================================

    custom_discounted(
        frm,
        cdt,
        cdn
    ) {

        recalculate_single_item(
            frm,
            cdt,
            cdn
        );
    },


    // ========================================================
    // WAREHOUSE
    // ========================================================

    warehouse(
        frm,
        cdt,
        cdn
    ) {

        enforce_quotation_item_warehouse(
            frm,
            cdt,
            cdn
        );
    }
});


// ============================================================
// QUERY SETUP
// ============================================================

function setup_quotation_queries(
    frm
) {

    // IMPORTANT:
    //
    // Do NOT add Branch.disabled filter.
    //
    // Standard Branch Link behavior is used.


    if (
        frm.fields_dict[
            SELECTED_WAREHOUSE_FIELD
        ]
    ) {

        frm.set_query(
            SELECTED_WAREHOUSE_FIELD,
            function () {

                const filters =
                    {};


                if (
                    frm.doc[COMPANY_FIELD]
                ) {

                    filters.company =
                        frm.doc[COMPANY_FIELD];
                }


                return {
                    filters:
                        filters
                };
            }
        );
    }
}


// ============================================================
// SALES ACCESS HIERARCHY DEFAULTS
// ============================================================
//
// One API request returns:
//
// {
//     company: "...",
//     branch: "..."
// }
//
// Company MUST be applied before Branch because Branch triggers
// warehouse and cost center validation.
// ============================================================

async function set_sales_defaults_from_hierarchy(
    frm
) {

    // --------------------------------------------------------
    // USER / DOCUMENT CHECK
    // --------------------------------------------------------

    if (
        !frappe.session.user ||
        frappe.session.user === "Guest" ||
        !frm.is_new()
    ) {
        return;
    }


    // --------------------------------------------------------
    // PREVENT DUPLICATE API CALL
    // --------------------------------------------------------

    if (
        frm.__loading_sales_defaults
    ) {
        return;
    }


    // --------------------------------------------------------
    // BOTH ALREADY PRESENT
    // --------------------------------------------------------

    if (
        frm.doc[COMPANY_FIELD] &&
        frm.doc[BRANCH_FIELD]
    ) {
        return;
    }


    frm.__loading_sales_defaults =
        true;


    try {

        // ----------------------------------------------------
        // GET USER SALES DEFAULTS
        // ----------------------------------------------------

        const response =
            await frappe.call({
                method:
                    "get_current_user_sales_defaults"
            });


        const defaults =
            response &&
            response.message
                ? response.message
                : {};


        const user_company =
            defaults.company || "";


        const user_branch =
            defaults.branch || "";


        // ----------------------------------------------------
        // COMPANY FIRST
        // ----------------------------------------------------

        if (
            user_company &&
            !frm.doc[COMPANY_FIELD]
        ) {

            await frm.set_value(
                COMPANY_FIELD,
                user_company
            );
        }


        // ----------------------------------------------------
        // BRANCH SECOND
        // ----------------------------------------------------

        if (
            user_branch &&
            !frm.doc[BRANCH_FIELD]
        ) {

            await frm.set_value(
                BRANCH_FIELD,
                user_branch
            );
        }


        // ----------------------------------------------------
        // DIAGNOSTIC WARNING
        // ----------------------------------------------------

        if (
            !user_company ||
            !user_branch
        ) {

            console.warn(
                "Sales Access Hierarchy defaults are incomplete.",
                {
                    company:
                        user_company,

                    branch:
                        user_branch
                }
            );
        }


    } catch (error) {

        console.error(
            "Unable to retrieve Sales Access Hierarchy defaults:",
            error
        );


    } finally {

        frm.__loading_sales_defaults =
            false;
    }
}


// ============================================================
// BRANCH MARKUP STATE
// ============================================================

function setup_branch_markup_flags(
    frm
) {

    if (
        frm._branch_markup_percentage ===
        undefined
    ) {

        frm._branch_markup_percentage =
            0;
    }


    if (
        frm._applying_branch_markup ===
        undefined
    ) {

        frm._applying_branch_markup =
            false;
    }
}


// ============================================================
// FULFILLMENT STATE
// ============================================================

function setup_quotation_fulfillment_flags(
    frm
) {

    // --------------------------------------------------------
    // SALES DEFAULT LOADING STATE
    // --------------------------------------------------------

    if (
        frm.__loading_sales_defaults ===
        undefined
    ) {

        frm.__loading_sales_defaults =
            false;
    }


    // --------------------------------------------------------
    // FULFILLMENT LOADING STATE
    // --------------------------------------------------------

    if (
        frm.__loading_fulfillment ===
        undefined
    ) {

        frm.__loading_fulfillment =
            false;
    }


    // --------------------------------------------------------
    // BRANCH COST CENTER
    // --------------------------------------------------------

    if (
        frm.__branch_cost_center ===
        undefined
    ) {

        frm.__branch_cost_center =
            "";
    }


    // --------------------------------------------------------
    // ACTIVE WAREHOUSE
    // --------------------------------------------------------

    if (
        frm.__selected_order_warehouse ===
        undefined
    ) {

        frm.__selected_order_warehouse =
            "";
    }


    // --------------------------------------------------------
    // BRANCH SETTINGS
    // --------------------------------------------------------

    if (
        frm.__branch_fulfillment_settings ===
        undefined
    ) {

        frm.__branch_fulfillment_settings =
            null;
    }
}


// ============================================================
// APPLY QUOTATION FULFILLMENT SETTINGS
// ============================================================

async function apply_quotation_fulfillment_settings(
    frm,
    show_message
) {

    if (
        frm.__loading_fulfillment
    ) {
        return;
    }


    const branch =
        frm.doc[
            BRANCH_FIELD
        ];


    if (
        !branch
    ) {
        return;
    }


    frm.__loading_fulfillment =
        true;


    try {

        // ----------------------------------------------------
        // LOAD BRANCH SETTINGS
        // ----------------------------------------------------

        const response =
            await frappe.db.get_value(
                "Branch",
                branch,
                [
                    BRANCH_DEFAULT_WAREHOUSE_FIELD,
                    BRANCH_CENTRAL_WAREHOUSE_FIELD,
                    BRANCH_COST_CENTER_FIELD,
                    BRANCH_ALLOW_CENTRAL_FIELD,
                    BRANCH_WAREHOUSE_COMPANY_FIELD
                ]
            );


        const settings =
            response &&
            response.message
                ? response.message
                : {};


        frm.__branch_fulfillment_settings =
            settings;


        // ----------------------------------------------------
        // DETERMINE CURRENT FULFILLMENT MODE
        // ----------------------------------------------------

        let central_enabled =
            cint(
                frm.doc[
                    CENTRAL_FULFILLMENT_FIELD
                ] || 0
            ) === 1;


        // ----------------------------------------------------
        // CENTRAL FULFILLMENT PERMISSION
        // ----------------------------------------------------

        if (
            central_enabled &&
            !cint(
                settings[
                    BRANCH_ALLOW_CENTRAL_FIELD
                ] || 0
            )
        ) {

            frappe.msgprint({

                title:
                    __(
                        "Central Fulfillment Not Enabled"
                    ),

                indicator:
                    "orange",

                message:
                    __(
                        "Central fulfillment is not enabled for branch {0}. Branch fulfillment will be used.",
                        [
                            branch
                        ]
                    )
            });


            await frm.set_value(
                CENTRAL_FULFILLMENT_FIELD,
                0
            );


            central_enabled =
                false;
        }


        // ----------------------------------------------------
        // DETERMINE WAREHOUSE
        // ----------------------------------------------------

        let selected_warehouse =
            "";


        if (
            central_enabled
        ) {

            selected_warehouse =
                settings[
                    BRANCH_CENTRAL_WAREHOUSE_FIELD
                ];

        } else {

            selected_warehouse =
                settings[
                    BRANCH_DEFAULT_WAREHOUSE_FIELD
                ];
        }


        // ----------------------------------------------------
        // WAREHOUSE REQUIRED
        // ----------------------------------------------------

        if (
            !selected_warehouse
        ) {

            if (
                central_enabled
            ) {

                frappe.throw(
                    __(
                        "Main Fulfillment Warehouse is not configured for branch {0}.",
                        [
                            branch
                        ]
                    )
                );
            }


            frappe.throw(
                __(
                    "Default Branch Warehouse is not configured for branch {0}.",
                    [
                        branch
                    ]
                )
            );
        }


        // ----------------------------------------------------
        // SELLING COST CENTER
        // ----------------------------------------------------

        const branch_cost_center =
            settings[
                BRANCH_COST_CENTER_FIELD
            ];


        if (
            !branch_cost_center
        ) {

            frappe.throw(
                __(
                    "Selling Cost Center is not configured for branch {0}.",
                    [
                        branch
                    ]
                )
            );
        }


        // ----------------------------------------------------
        // VALIDATE WAREHOUSE
        // ----------------------------------------------------

        await validate_quotation_warehouse(
            frm,
            selected_warehouse,
            central_enabled,
            settings
        );


        // ----------------------------------------------------
        // VALIDATE COST CENTER
        // ----------------------------------------------------

        await validate_quotation_cost_center(
            frm,
            branch_cost_center
        );


        // ----------------------------------------------------
        // STORE ACTIVE SETTINGS
        // ----------------------------------------------------

        frm.__branch_cost_center =
            branch_cost_center;


        frm.__selected_order_warehouse =
            selected_warehouse;


        // ----------------------------------------------------
        // SET HEADER FULFILLMENT WAREHOUSE
        // ----------------------------------------------------

        if (
            frm.doc[
                SELECTED_WAREHOUSE_FIELD
            ] !== selected_warehouse
        ) {

            await frm.set_value(
                SELECTED_WAREHOUSE_FIELD,
                selected_warehouse
            );
        }


        // ----------------------------------------------------
        // APPLY TO ALL ITEMS
        // ----------------------------------------------------

        await apply_fulfillment_to_all_items(
            frm
        );


        // ----------------------------------------------------
        // USER ALERT
        // ----------------------------------------------------

        if (
            show_message
        ) {

            frappe.show_alert({

                message:
                    central_enabled
                        ? __(
                            "Central fulfillment applied. Warehouse: {0}. Cost Center: {1}.",
                            [
                                selected_warehouse,
                                branch_cost_center
                            ]
                        )
                        : __(
                            "Branch fulfillment applied. Warehouse: {0}. Cost Center: {1}.",
                            [
                                selected_warehouse,
                                branch_cost_center
                            ]
                        ),

                indicator:
                    central_enabled
                        ? "blue"
                        : "green"
            });
        }


    } finally {

        frm.__loading_fulfillment =
            false;
    }
}


// ============================================================
// VALIDATE QUOTATION WAREHOUSE
// ============================================================

async function validate_quotation_warehouse(
    frm,
    warehouse_name,
    central_enabled,
    branch_settings
) {

    const response =
        await frappe.db.get_value(
            "Warehouse",
            warehouse_name,
            [
                "name",
                "company",
                "is_group"
            ]
        );


    const warehouse =
        response &&
        response.message
            ? response.message
            : {};


    // --------------------------------------------------------
    // WAREHOUSE EXISTS
    // --------------------------------------------------------

    if (
        !warehouse.name
    ) {

        frappe.throw(
            __(
                "Warehouse {0} could not be found.",
                [
                    warehouse_name
                ]
            )
        );
    }


    // --------------------------------------------------------
    // WAREHOUSE COMPANY MATCH
    // --------------------------------------------------------

    if (
        frm.doc[COMPANY_FIELD] &&
        warehouse.company !==
            frm.doc[COMPANY_FIELD]
    ) {

        frappe.throw(
            __(
                "Warehouse {0} belongs to company {1}, but this Quotation belongs to company {2}.",
                [
                    warehouse_name,
                    warehouse.company,
                    frm.doc[COMPANY_FIELD]
                ]
            )
        );
    }


    // --------------------------------------------------------
    // CONFIGURED BRANCH COMPANY
    // --------------------------------------------------------

    const configured_company =
        branch_settings[
            BRANCH_WAREHOUSE_COMPANY_FIELD
        ];


    if (
        configured_company &&
        frm.doc[COMPANY_FIELD] &&
        configured_company !==
            frm.doc[COMPANY_FIELD]
    ) {

        frappe.throw(
            __(
                "Branch {0} is configured for company {1}, but this Quotation belongs to company {2}.",
                [
                    frm.doc[
                        BRANCH_FIELD
                    ],
                    configured_company,
                    frm.doc[
                        COMPANY_FIELD
                    ]
                ]
            )
        );
    }


    // --------------------------------------------------------
    // ORDINARY BRANCH WAREHOUSE MUST NOT BE GROUP
    // --------------------------------------------------------

    if (
        !central_enabled &&
        cint(
            warehouse.is_group
        )
    ) {

        frappe.throw(
            __(
                "Default Branch Warehouse {0} is a group warehouse. Configure an actual non-group warehouse.",
                [
                    warehouse_name
                ]
            )
        );
    }
}


// ============================================================
// VALIDATE QUOTATION COST CENTER
// ============================================================

async function validate_quotation_cost_center(
    frm,
    cost_center
) {

    const response =
        await frappe.db.get_value(
            "Cost Center",
            cost_center,
            [
                "name",
                "company"
            ]
        );


    const values =
        response &&
        response.message
            ? response.message
            : {};


    // --------------------------------------------------------
    // COST CENTER EXISTS
    // --------------------------------------------------------

    if (
        !values.name
    ) {

        frappe.throw(
            __(
                "Selling Cost Center {0} could not be found.",
                [
                    cost_center
                ]
            )
        );
    }


    // --------------------------------------------------------
    // COST CENTER COMPANY MATCH
    // --------------------------------------------------------

    if (
        frm.doc[COMPANY_FIELD] &&
        values.company !==
            frm.doc[COMPANY_FIELD]
    ) {

        frappe.throw(
            __(
                "Selling Cost Center {0} belongs to company {1}, but this Quotation belongs to company {2}.",
                [
                    cost_center,
                    values.company,
                    frm.doc[
                        COMPANY_FIELD
                    ]
                ]
            )
        );
    }
}


// ============================================================
// APPLY FULFILLMENT TO ALL ITEMS
// ============================================================

async function apply_fulfillment_to_all_items(
    frm
) {

    for (
        const row of
        frm.doc.items || []
    ) {

        await apply_item_fulfillment_settings(
            frm,
            row.doctype,
            row.name
        );
    }


    frm.refresh_field(
        "items"
    );
}


// ============================================================
// APPLY FULFILLMENT TO ONE ITEM
// ============================================================

async function apply_item_fulfillment_settings(
    frm,
    cdt,
    cdn
) {

    const row =
        locals[cdt][cdn];


    if (
        !row
    ) {
        return;
    }


    const selected_warehouse =
        frm.__selected_order_warehouse ||
        frm.doc[
            SELECTED_WAREHOUSE_FIELD
        ];


    const cost_center =
        frm.__branch_cost_center;


    // --------------------------------------------------------
    // WAREHOUSE
    // --------------------------------------------------------

    if (
        selected_warehouse &&
        row.warehouse !==
            selected_warehouse
    ) {

        await frappe.model.set_value(
            cdt,
            cdn,
            "warehouse",
            selected_warehouse
        );
    }


    // --------------------------------------------------------
    // COST CENTER
    // --------------------------------------------------------

    if (
        cost_center &&
        row.cost_center !== undefined &&
        row.cost_center !== cost_center
    ) {

        await frappe.model.set_value(
            cdt,
            cdn,
            "cost_center",
            cost_center
        );
    }
}


// ============================================================
// PREVENT MANUAL WAREHOUSE OVERRIDE
// ============================================================

async function enforce_quotation_item_warehouse(
    frm,
    cdt,
    cdn
) {

    if (
        frm.__loading_fulfillment
    ) {
        return;
    }


    const row =
        locals[cdt][cdn];


    if (
        !row ||
        !row.warehouse
    ) {
        return;
    }


    const expected_warehouse =
        frm.__selected_order_warehouse ||
        frm.doc[
            SELECTED_WAREHOUSE_FIELD
        ];


    if (
        expected_warehouse &&
        row.warehouse !==
            expected_warehouse
    ) {

        frappe.msgprint(
            __(
                "Item warehouse must be {0}.",
                [
                    expected_warehouse
                ]
            )
        );


        await frappe.model.set_value(
            cdt,
            cdn,
            "warehouse",
            expected_warehouse
        );
    }
}


// ============================================================
// FINAL QUOTATION FULFILLMENT VALIDATION
// ============================================================

function validate_quotation_fulfillment(
    frm
) {

    // --------------------------------------------------------
    // COMPANY
    // --------------------------------------------------------

    if (
        !frm.doc[
            COMPANY_FIELD
        ]
    ) {

        frappe.throw(
            __(
                "Company is required."
            )
        );
    }


    // --------------------------------------------------------
    // BRANCH
    // --------------------------------------------------------

    if (
        !frm.doc[
            BRANCH_FIELD
        ]
    ) {

        frappe.throw(
            __(
                "Branch is required."
            )
        );
    }


    // --------------------------------------------------------
    // FULFILLMENT WAREHOUSE
    // --------------------------------------------------------

    if (
        !frm.doc[
            SELECTED_WAREHOUSE_FIELD
        ]
    ) {

        frappe.throw(
            __(
                "Order Fulfillment Warehouse is required."
            )
        );
    }


    const expected_warehouse =
        frm.__selected_order_warehouse ||
        frm.doc[
            SELECTED_WAREHOUSE_FIELD
        ];


    // --------------------------------------------------------
    // ITEM WAREHOUSES
    // --------------------------------------------------------

    for (
        const row of
        frm.doc.items || []
    ) {

        if (
            expected_warehouse &&
            row.warehouse !==
                expected_warehouse
        ) {

            frappe.throw(
                __(
                    "Row {0}: Warehouse must be {1}.",
                    [
                        row.idx,
                        expected_warehouse
                    ]
                )
            );
        }
    }
}


// ============================================================
// CLEAR FULFILLMENT VALUES
// ============================================================

async function clear_quotation_fulfillment_fields(
    frm
) {

    // --------------------------------------------------------
    // HEADER WAREHOUSE
    // --------------------------------------------------------

    if (
        frm.doc[
            SELECTED_WAREHOUSE_FIELD
        ]
    ) {

        await frm.set_value(
            SELECTED_WAREHOUSE_FIELD,
            ""
        );
    }


    // --------------------------------------------------------
    // ITEM VALUES
    // --------------------------------------------------------

    for (
        const row of
        frm.doc.items || []
    ) {

        if (
            row.warehouse
        ) {

            await frappe.model.set_value(
                row.doctype,
                row.name,
                "warehouse",
                ""
            );
        }


        if (
            row.cost_center
        ) {

            await frappe.model.set_value(
                row.doctype,
                row.name,
                "cost_center",
                ""
            );
        }
    }


    frm.refresh_field(
        "items"
    );
}


// ============================================================
// BRANCH MARKUP LOADING
// ============================================================

function load_branch_markup(
    frm
) {

    if (
        !frm.doc[
            BRANCH_FIELD
        ]
    ) {

        frm._branch_markup_percentage =
            0;


        return Promise.resolve(
            0
        );
    }


    return frappe.db.get_list(
        "Branch Markup Setting",
        {

            filters: {

                branch:
                    frm.doc[
                        BRANCH_FIELD
                    ],

                enabled:
                    1
            },


            fields: [
                "markup_percentage"
            ],


            limit:
                1

        }
    ).then(

        function (
            records
        ) {

            let markup_percentage =
                0;


            if (
                records &&
                records.length > 0
            ) {

                markup_percentage =
                    flt(
                        records[0]
                            .markup_percentage
                    );
            }


            frm._branch_markup_percentage =
                markup_percentage;


            return markup_percentage;
        }
    );
}


// ============================================================
// RECALCULATE ALL ITEMS
// ============================================================

function recalculate_all_items(
    frm
) {

    if (
        !frm.doc[
            BRANCH_FIELD
        ]
    ) {
        return;
    }


    if (
        !frm.doc.items ||
        frm.doc.items.length === 0
    ) {
        return;
    }


    frm.doc.items.forEach(

        function (
            row
        ) {

            recalculate_item_row(
                frm,
                row.doctype,
                row.name
            );
        }
    );


    frm.refresh_field(
        "items"
    );
}


// ============================================================
// RECALCULATE ONE ITEM
// ============================================================

function recalculate_single_item(
    frm,
    cdt,
    cdn
) {

    setup_branch_markup_flags(
        frm
    );


    if (
        !frm.doc[
            BRANCH_FIELD
        ]
    ) {
        return;
    }


    const row =
        locals[cdt][cdn];


    if (
        !row ||
        !row.item_code
    ) {
        return;
    }


    load_branch_markup(
        frm
    ).then(

        function () {

            recalculate_item_row(
                frm,
                cdt,
                cdn
            );


            frm.refresh_field(
                "items"
            );
        }
    );
}


// ============================================================
// ITEM PRICING
// ============================================================

function recalculate_item_row(
    frm,
    cdt,
    cdn
) {

    const row =
        locals[cdt][cdn];


    if (
        !row ||
        !row.item_code
    ) {
        return;
    }


    let qty =
        flt(
            row.qty
        );


    if (
        qty <= 0
    ) {

        qty =
            1;
    }


    // --------------------------------------------------------
    // ORIGINAL BASE RATE
    // --------------------------------------------------------

    const base_rate =
        get_base_rate(
            row
        );


    if (
        !base_rate
    ) {
        return;
    }


    // --------------------------------------------------------
    // MARKUP
    // --------------------------------------------------------

    const markup_percentage =
        flt(
            frm._branch_markup_percentage
        );


    const marked_up_rate =
        base_rate +
        (
            base_rate *
            markup_percentage /
            100
        );


    // --------------------------------------------------------
    // DISCOUNT
    //
    // custom_discounted = TOTAL ROW VALUE
    // --------------------------------------------------------

    const total_discounted_price =
        flt(
            row[
                TOTAL_DISCOUNTED_FIELD
            ]
        );


    let final_rate =
        marked_up_rate;


    if (
        total_discounted_price > 0
    ) {

        final_rate =
            total_discounted_price /
            qty;
    }


    // --------------------------------------------------------
    // APPLY PRICES
    // --------------------------------------------------------

    frm._applying_branch_markup =
        true;


    frappe.model.set_value(
        cdt,
        cdn,
        BASE_RATE_FIELD,
        base_rate
    );


    frappe.model.set_value(
        cdt,
        cdn,
        MARKUP_PERCENT_FIELD,
        markup_percentage
    );


    frappe.model.set_value(
        cdt,
        cdn,
        MARKED_UP_RATE_FIELD,
        marked_up_rate
    );


    frappe.model.set_value(
        cdt,
        cdn,
        "rate",
        final_rate
    );


    setTimeout(

        function () {

            frm._applying_branch_markup =
                false;
        },

        200
    );
}


// ============================================================
// GET BASE RATE
// ============================================================

function get_base_rate(
    row
) {

    // --------------------------------------------------------
    // STORED BASE RATE
    // --------------------------------------------------------

    const stored_base_rate =
        flt(
            row[
                BASE_RATE_FIELD
            ]
        );


    if (
        stored_base_rate > 0
    ) {

        return stored_base_rate;
    }


    // --------------------------------------------------------
    // PRICE LIST RATE
    // --------------------------------------------------------

    if (
        flt(
            row.price_list_rate
        ) > 0
    ) {

        return flt(
            row.price_list_rate
        );
    }


    // --------------------------------------------------------
    // CURRENT RATE FALLBACK
    // --------------------------------------------------------

    if (
        flt(
            row.rate
        ) > 0
    ) {

        return flt(
            row.rate
        );
    }


    return 0;
}


// ============================================================
// CLEAR ONE ROW MARKUP
// ============================================================

function clear_row_markup_values(
    cdt,
    cdn
) {

