// ============================================================
// GET FLAG CONTAINER
// ============================================================

function get_quotation_fulfillment_flag_container(
    frm
) {

    if (
        !frm ||
        !frm.page ||
        !frm.page.wrapper
    ) {

        return null;
    }


    const $page_wrapper =
        $(
            frm.page.wrapper
        );


    // --------------------------------------------------------
    // PREFERRED CONTAINER
    // --------------------------------------------------------

    const $form_layout =
        $page_wrapper
            .find(
                ".form-layout"
            )
            .first();


    if (
        $form_layout.length
    ) {

        return $form_layout;
    }


    // --------------------------------------------------------
    // FALLBACK
    // --------------------------------------------------------

    const $page_body =
        $page_wrapper
            .find(
                ".page-body"
            )
            .first();


    if (
        $page_body.length
    ) {

        return $page_body;
    }


    return $page_wrapper;
}


