}


// ============================================================
// UPDATE / CREATE FULFILLMENT FLAG
// ============================================================

function update_quotation_fulfillment_flag(
    frm
) {

    // --------------------------------------------------------
    // REQUIRED DATA
    // --------------------------------------------------------

    if (
        !frm.doc[
            BRANCH_FIELD
        ] ||
        !frm.doc[
            SELECTED_WAREHOUSE_FIELD
        ]
    ) {

        remove_quotation_fulfillment_flag(
            frm
        );

        return;
    }


    // --------------------------------------------------------
    // FULFILLMENT MODE
    // --------------------------------------------------------

    const central_enabled =
        cint(
            frm.doc[
                CENTRAL_FULFILLMENT_FIELD
            ] || 0
        ) === 1;


    const branch =
        frappe.utils.escape_html(
            frm.doc[
                BRANCH_FIELD
            ]
        );


    const warehouse =
        frappe.utils.escape_html(
            frm.doc[
                SELECTED_WAREHOUSE_FIELD
            ]
        );


    // --------------------------------------------------------
    // TITLE / DESCRIPTION
    // --------------------------------------------------------

    const title =
        central_enabled
            ? __(
                "Central Fulfillment"
            )
            : __(
                "Branch Fulfillment"
            );


    const description =
        central_enabled
            ? __(
                "The main warehouse will pick, pack, and deliver this order."
            )
            : __(
                "The selling branch warehouse will fulfill this order."
            );


    // --------------------------------------------------------
    // COLORS
    // --------------------------------------------------------

    const background_color =
        central_enabled
            ? "rgba(33, 150, 243, 0.12)"
            : "rgba(40, 167, 69, 0.12)";


    const border_color =
        central_enabled
            ? "#2196f3"
            : "#28a745";


    const title_color =
        central_enabled
            ? "#1976d2"
            : "#218838";


    const icon =
        central_enabled
            ? "🏢"
            : "🏬";


    // --------------------------------------------------------
    // HTML
    // --------------------------------------------------------

    const html =
        `
        <div
            class="${QUOTATION_FULFILLMENT_FLAG_CLASS}"
            data-central-fulfillment="${
                central_enabled
                    ? "1"
                    : "0"
            }"
            style="
                margin: 8px 0 12px 0;
                padding: 12px 14px;
                border: 1px solid ${border_color};
                border-left: 5px solid ${border_color};
                border-radius: 6px;
                background: ${background_color};
                line-height: 1.5;
            "
        >

            <div
                style="
                    display: flex;
                    align-items: center;
                    gap: 7px;
                    font-weight: 700;
                    font-size: 14px;
                    color: ${title_color};
                    margin-bottom: 5px;
                "
            >

                <span>
                    ${icon}
                </span>

                <span>
                    ${title}
                </span>

            </div>


            <div>

                ${__("Selling Branch")}:

                <b>
                    ${branch}
                </b>

            </div>


            <div>

                ${__("Physical Stock Source")}:

                <b>
                    ${warehouse}
                </b>

            </div>


            <div
                style="
                    margin-top: 5px;
                "
            >

                ${description}

            </div>

        </div>
        `;


    // --------------------------------------------------------
    // FIND EXISTING FLAG
    // --------------------------------------------------------

    const $page_wrapper =
        $(
            frm.page.wrapper
        );


    let $existing =
        $page_wrapper
            .find(
                "." +
                QUOTATION_FULFILLMENT_FLAG_CLASS
            );


    // --------------------------------------------------------
    // REMOVE DUPLICATES
    // --------------------------------------------------------

    if (
        $existing.length > 1
    ) {

        $existing
            .slice(1)
            .remove();


        $existing =
            $page_wrapper
                .find(
                    "." +
                    QUOTATION_FULFILLMENT_FLAG_CLASS
                )
                .first();
    }


    // --------------------------------------------------------
    // UPDATE EXISTING FLAG
    // --------------------------------------------------------

    if (
        $existing.length
    ) {

        $existing.replaceWith(
            html
        );

        return;
    }


    // --------------------------------------------------------
    // CREATE NEW FLAG
    // --------------------------------------------------------

    const $container =
        get_quotation_fulfillment_flag_container(
            frm
        );


    if (
        !$container
    ) {

        return;
    }


    if (
        $container.hasClass(
            "form-layout"
        )
    ) {

        $container.before(
            html
        );

    } else {

        $container.prepend(
            html
        );
    }
}

// Client Script: Sales Order Branch Markup
// Purpose:
// Automatically add branch-based markup to every Sales Order Item rate.
// Example: Subic branch = 5% markup.
// Required:
// 1. Sales Order.custom_branch
// 2. Branch Markup Setting DocType
// 3. Sales Order Item.custom_base_rate_before_markup
// 4. Sales Order Item.custom_branch_markup_percentage

frappe.ui.form.on("Sales Order", {
    custom_branch: function(frm) {
        apply_branch_markup_to_sales_order(frm);
    },

    items_add: function(frm) {
        apply_branch_markup_to_sales_order(frm);
    },

    validate: function(frm) {
        apply_branch_markup_to_sales_order(frm);
    }
});

frappe.ui.form.on("Sales Order Item", {
    item_code: function(frm, cdt, cdn) {
        apply_branch_markup_to_sales_order(frm);
    },

    rate: function(frm, cdt, cdn) {
        store_original_rate_if_needed(frm, cdt, cdn);
    },

    price_list_rate: function(frm, cdt, cdn) {
        apply_branch_markup_to_sales_order(frm);
    }
});

function apply_branch_markup_to_sales_order(frm) {
    if (!frm.doc.custom_branch) {
        return;
    }

    frappe.db.get_list("Branch Markup Setting", {
        filters: {
            branch: frm.doc.custom_branch,
            enabled: 1
        },
        fields: ["markup_percentage"],
        limit: 1
    }).then(function(records) {
        let markup_percentage = 0;

        if (records && records.length > 0) {
            markup_percentage = flt(records[0].markup_percentage);
        }

        apply_markup_to_items(frm, markup_percentage);
    });
}

function apply_markup_to_items(frm, markup_percentage) {
    if (!frm.doc.items || frm.doc.items.length === 0) {
        return;
    }

    frm.doc.items.forEach(function(row) {
        let base_rate = flt(row.custom_base_rate_before_markup);

        if (!base_rate) {
            if (flt(row.price_list_rate)) {
                base_rate = flt(row.price_list_rate);
            } else {
                base_rate = flt(row.rate);
            }

            frappe.model.set_value(
                row.doctype,
                row.name,
                "custom_base_rate_before_markup",
                base_rate
            );
        }

        let new_rate = base_rate + (base_rate * markup_percentage / 100);

        frappe.model.set_value(
            row.doctype,
            row.name,
            "custom_branch_markup_percentage",
            markup_percentage
        );

        frappe.model.set_value(
            row.doctype,
            row.name,
            "rate",
            new_rate
        );
    });

    frm.refresh_field("items");
}

function store_original_rate_if_needed(frm, cdt, cdn) {
    let row = locals[cdt][cdn];

    if (!row) {
        return;
    }

    if (!flt(row.custom_base_rate_before_markup) && flt(row.rate)) {
        frappe.model.set_value(
            cdt,
            cdn,
            "custom_base_rate_before_markup",
            flt(row.rate)
        );
    }
}

// Client Script: Sales Order Copy Quotation Pricing
// DocType: Sales Order
//
// Final behavior:
// - SO Item.rate = Quotation Item.rate
// - SO Item.custom_discount = Quotation Item.custom_discounted
// - SO parent discount section is cleared

frappe.ui.form.on("Sales Order", {
    onload: function(frm) {
        if (frm.is_new()) {
            setTimeout(function() {
                copy_quotation_pricing_to_sales_order(frm);
            }, 1000);
        }
    },

    refresh: function(frm) {
        if (frm.is_new()) {
            setTimeout(function() {
                copy_quotation_pricing_to_sales_order(frm);
            }, 1000);
        }
    },

    validate: function(frm) {
        clear_sales_order_parent_discount(frm);
    }
});

function copy_quotation_pricing_to_sales_order(frm) {
    if (!frm.doc.items || frm.doc.items.length === 0) {
        clear_sales_order_parent_discount(frm);
        return;
    }

    let promises = [];

    frm.doc.items.forEach(function(row) {
        let quotation_item_name = "";

        if (row.prevdoc_detail_docname) {
            quotation_item_name = row.prevdoc_detail_docname;
        }

        if (!quotation_item_name && row.quotation_item) {
            quotation_item_name = row.quotation_item;
        }

        if (!quotation_item_name && row.custom_quotation_item) {
            quotation_item_name = row.custom_quotation_item;
        }

        if (!quotation_item_name) {
            return;
        }

        let p = frappe.db.get_value(
            "Quotation Item",
            quotation_item_name,
            [
                "rate",
                "custom_base_rate_before_markup",
                "custom_branch_markup_percentage",
                "custom_marked_up_rate",
                "custom_discounted"
            ]
        ).then(function(r) {
            if (!r || !r.message) {
                return;
            }

            let q = r.message;

            frappe.model.set_value(row.doctype, row.name, "custom_base_rate_before_markup", flt(q.custom_base_rate_before_markup));
            frappe.model.set_value(row.doctype, row.name, "custom_branch_markup_percentage", flt(q.custom_branch_markup_percentage));
            frappe.model.set_value(row.doctype, row.name, "custom_marked_up_rate", flt(q.custom_marked_up_rate));

            // Quotation Item.custom_discounted -> Sales Order Item.custom_discount
            frappe.model.set_value(row.doctype, row.name, "custom_discount", flt(q.custom_discounted));

            // Must be exactly same as Quotation Item.rate
            frappe.model.set_value(row.doctype, row.name, "rate", flt(q.rate));
        });

        promises.push(p);
    });

    Promise.all(promises).then(function() {
        clear_sales_order_parent_discount(frm);
        frm.refresh_field("items");
    });
}

function clear_sales_order_parent_discount(frm) {
    frm.set_value("apply_discount_on", "Grand Total");
    frm.set_value("additional_discount_percentage", 0);
    frm.set_value("discount_amount", 0);

    frm.refresh_field("apply_discount_on");
    frm.refresh_field("additional_discount_percentage");
    frm.refresh_field("discount_amount");
}

