function control_print_button_by_workflow(frm) {
    let approved_state = "Approved";

    // Run several times because Frappe rebuilds buttons after save/refresh
    setTimeout(function() {
        apply_print_visibility(frm, approved_state);
    }, 100);

    setTimeout(function() {
        apply_print_visibility(frm, approved_state);
    }, 500);

    setTimeout(function() {
        apply_print_visibility(frm, approved_state);
    }, 1000);

