function hide_print_buttons(frm) {
    // Hide the main Frappe print button
    if (frm.page && frm.page.btn_print) {
        frm.page.btn_print.hide();
    }

    // Hide standard toolbar/menu print options
    $('[data-label="Print"]').hide();
    $('[data-original-title="Print"]').hide();
    $('[title="Print"]').hide();

    // Hide buttons/links with Print text
    $('button').filter(function() {
        return $(this).text().trim() === "Print";
    }).hide();

    $('a').filter(function() {
        return $(this).text().trim() === "Print";
    }).hide();

    // Hide print icon buttons
    $('.fa-print').closest('button').hide();
    $('.fa-print').closest('a').hide();

    // Hide Menu > Print
    $('.dropdown-menu a').filter(function() {
        return $(this).text().trim() === "Print";
    }).hide();
}


function show_print_buttons(frm) {
    if (frm.page && frm.page.btn_print) {
        frm.page.btn_print.show();
    }

    $('[data-label="Print"]').show();
    $('[data-original-title="Print"]').show();
    $('[title="Print"]').show();

    $('button').filter(function() {
        return $(this).text().trim() === "Print";
    }).show();

    $('a').filter(function() {
        return $(this).text().trim() === "Print";
    }).show();

    $('.fa-print').closest('button').show();
    $('.fa-print').closest('a').show();

    $('.dropdown-menu a').filter(function() {
        return $(this).text().trim() === "Print";
    }).show();
}

