/* =========================================================
   CENTRAL FULFILLMENT SETUP
   ========================================================= */

function setup_delivery_note_queries(frm) {
    if (frm.fields_dict.branch) {
        frm.set_query("branch", function () {
            return {
                filters: {
                    disabled: 0
                }
            };
        });
    }

    if (frm.fields_dict.custom_fulfillment_warehouse) {
        frm.set_query(
            "custom_fulfillment_warehouse",
            function () {
                const filters = {};

                if (frm.doc.company) {
                    filters.company = frm.doc.company;
                }

                return {
                    filters: filters
                };
            }
        );
    }
}


/* =========================================================
   LOAD CENTRAL FULFILLMENT DATA
   ========================================================= */

async function load_delivery_note_fulfillment_data(frm) {
    if (frm._loading_delivery_fulfillment) {
        return;
    }

    const sales_orders = get_delivery_note_sales_orders(frm);

    if (!sales_orders.length) {
        return;
    }

    frm._loading_delivery_fulfillment = true;

    try {
        let selected_branch = "";
        let selected_fulfillment_warehouse = "";
        let centralized_order_found = false;

        for (const sales_order of sales_orders) {
            const response = await frappe.db.get_value(
                "Sales Order",
                sales_order,
                [
                    "company",
                    "branch",
                    "custom_fulfillment_warehouse",
                    "custom_central_fulfillment"
                ]
            );

            const values = response && response.message ? response.message : {};

            if (!cint(values.custom_central_fulfillment)) {
                continue;
            }

            centralized_order_found = true;

            if (
                values.company &&
                frm.doc.company &&
                values.company !== frm.doc.company
            ) {
                frappe.throw(
                    __(
                        "Sales Order {0} belongs to company {1}, but this Delivery Note belongs to company {2}.",
                        [
                            sales_order,
                            values.company,
                            frm.doc.company
                        ]
                    )
                );
            }

            if (!values.branch) {
                frappe.throw(
                    __(
                        "Branch is missing from Sales Order {0}.",
                        [sales_order]
                    )
                );
            }

            if (!values.custom_fulfillment_warehouse) {
                frappe.throw(
                    __(
                        "Fulfillment Warehouse is missing from Sales Order {0}.",
                        [sales_order]
                    )
                );
            }

            if (!selected_branch) {
                selected_branch = values.branch;
            } else if (selected_branch !== values.branch) {
                frappe.throw(
                    __(
                        "A centralized Delivery Note cannot contain Sales Orders from different branches."
                    )
                );
            }

            if (!selected_fulfillment_warehouse) {
                selected_fulfillment_warehouse =
                    values.custom_fulfillment_warehouse;
            } else if (
                selected_fulfillment_warehouse !==
                values.custom_fulfillment_warehouse
            ) {
                frappe.throw(
                    __(
                        "A centralized Delivery Note cannot contain Sales Orders with different fulfillment warehouses."
                    )
                );
            }
        }

        if (!centralized_order_found) {
            return;
        }

        frm.__central_fulfillment_enabled = true;
        frm.__central_fulfillment_branch = selected_branch;
        frm.__central_fulfillment_warehouse = selected_fulfillment_warehouse;

        if (
            frm.fields_dict.branch &&
            frm.doc.branch !== selected_branch
        ) {
            await frm.set_value(
                "branch",
                selected_branch
            );
        }

        if (
            frm.fields_dict.custom_fulfillment_warehouse &&
            frm.doc.custom_fulfillment_warehouse !== selected_fulfillment_warehouse
        ) {
            await frm.set_value(
                "custom_fulfillment_warehouse",
                selected_fulfillment_warehouse
            );
        }

        await load_branch_cost_center(frm);
        await validate_all_delivery_warehouses(frm);
        show_delivery_note_fulfillment_banner(frm);

    } catch (error) {
        console.error(
            "Delivery Note central fulfillment failed:",
            error
        );

        throw error;

    } finally {
        frm._loading_delivery_fulfillment = false;
    }
}


function get_delivery_note_sales_orders(frm) {
    const sales_orders = [];

    (frm.doc.items || []).forEach(function (row) {
        const sales_order = clean_delivery_value(
            row.against_sales_order
        );

        if (
            sales_order &&
            !sales_orders.includes(sales_order)
        ) {
            sales_orders.push(sales_order);
        }
    });

    return sales_orders;
}


/* =========================================================
   BRANCH COST CENTER
   ========================================================= */

async function load_branch_cost_center(frm) {
    const branch =
        frm.doc.branch ||
        frm.__central_fulfillment_branch;

    if (!branch) {
        return;
    }

    const response = await frappe.db.get_value(
        "Branch",
        branch,
        "custom_selling_cost_center"
    );

    const cost_center =
        response && response.message
            ? response.message.custom_selling_cost_center
            : "";

    if (!cost_center) {
        if (frm.__central_fulfillment_enabled) {
            frappe.throw(
                __(
                    "Selling Cost Center is not configured for branch {0}.",
                    [branch]
                )
            );
        }

        return;
    }

    frm.__branch_cost_center = cost_center;

    for (const row of frm.doc.items || []) {
        if (row.cost_center !== cost_center) {
            await frappe.model.set_value(
                row.doctype,
                row.name,
                "cost_center",
                cost_center
            );
        }
    }

    frm.refresh_field("items");
}


