/* =========================================================
   DELIVERY NOTE VALIDATION
   ========================================================= */

async function validate_delivery_note_fulfillment(frm) {
    const sales_orders = get_delivery_note_sales_orders(frm);

    if (!sales_orders.length) {
        return;
    }

    await load_delivery_note_fulfillment_data(frm);

    if (!frm.__central_fulfillment_enabled) {
        return;
    }

    if (!frm.doc.branch) {
        frappe.throw(
            __(
                "Branch is required for centralized fulfillment."
            )
        );
    }

    if (!frm.doc.custom_fulfillment_warehouse) {
        frappe.throw(
            __(
                "Fulfillment Warehouse is required for centralized fulfillment."
            )
        );
    }

    await validate_all_delivery_warehouses(frm);
}


async function validate_all_delivery_warehouses(frm) {
    if (!frm.__central_fulfillment_enabled) {
        return;
    }

    const fulfillment_warehouse =
        frm.doc.custom_fulfillment_warehouse ||
        frm.__central_fulfillment_warehouse;

    if (!fulfillment_warehouse) {
        return;
    }

    const root_response = await frappe.db.get_value(
        "Warehouse",
        fulfillment_warehouse,
        [
            "name",
            "company",
            "is_group",
            "lft",
            "rgt"
        ]
    );

    const root =
        root_response && root_response.message
            ? root_response.message
            : {};

    if (!root.name) {
        frappe.throw(
            __(
                "Fulfillment Warehouse {0} could not be found.",
                [fulfillment_warehouse]
            )
        );
    }

    if (
        root.company &&
        frm.doc.company &&
        root.company !== frm.doc.company
    ) {
        frappe.throw(
            __(
                "Fulfillment Warehouse {0} belongs to company {1}, but this Delivery Note belongs to company {2}.",
                [
                    fulfillment_warehouse,
                    root.company,
                    frm.doc.company
                ]
            )
        );
    }

    for (const row of frm.doc.items || []) {
        if (!row.warehouse) {
            frappe.throw(
                __(
                    "Row {0}: Source Warehouse is required.",
                    [row.idx]
                )
            );
        }

        await validate_delivery_warehouse_against_root(
            frm,
            row,
            root
        );
    }
}


async function validate_delivery_note_item_warehouse(
    frm,
    cdt,
    cdn
) {
    if (
        frm._validating_delivery_warehouse ||
        !frm.__central_fulfillment_enabled
    ) {
        return;
    }

    const row = locals[cdt][cdn];

    if (!row || !row.warehouse) {
        return;
    }

    const fulfillment_warehouse =
        frm.doc.custom_fulfillment_warehouse ||
        frm.__central_fulfillment_warehouse;

    if (!fulfillment_warehouse) {
        return;
    }

    frm._validating_delivery_warehouse = true;

    try {
        const root_response = await frappe.db.get_value(
            "Warehouse",
            fulfillment_warehouse,
            [
                "name",
                "company",
                "lft",
                "rgt"
            ]
        );

        const root =
            root_response && root_response.message
                ? root_response.message
                : {};

        if (!root.name) {
            return;
        }

        await validate_delivery_warehouse_against_root(
            frm,
            row,
            root
        );

    } catch (error) {
        console.error(error);

        await frappe.model.set_value(
            cdt,
            cdn,
            "warehouse",
            ""
        );

    } finally {
        frm._validating_delivery_warehouse = false;
    }
}


async function validate_delivery_warehouse_against_root(
    frm,
    row,
    root
) {
    const response = await frappe.db.get_value(
        "Warehouse",
        row.warehouse,
        [
            "name",
            "company",
            "is_group",
            "lft",
            "rgt"
        ]
    );

    const warehouse =
        response && response.message
            ? response.message
            : {};

    if (!warehouse.name) {
        frappe.throw(
            __(
                "Row {0}: Warehouse {1} could not be found.",
                [
                    row.idx,
                    row.warehouse
                ]
            )
        );
    }

    if (
        warehouse.company &&
        frm.doc.company &&
        warehouse.company !== frm.doc.company
    ) {
        frappe.throw(
            __(
                "Row {0}: Warehouse {1} belongs to company {2}, not company {3}.",
                [
                    row.idx,
                    row.warehouse,
                    warehouse.company,
                    frm.doc.company
                ]
            )
        );
    }

    if (cint(warehouse.is_group)) {
        frappe.throw(
            __(
                "Row {0}: Group warehouse {1} cannot be used for delivery. Select an actual child or bin warehouse.",
                [
                    row.idx,
                    row.warehouse
                ]
            )
        );
    }

    const warehouse_is_under_root =
        flt(warehouse.lft) >= flt(root.lft) &&
        flt(warehouse.rgt) <= flt(root.rgt);

    if (!warehouse_is_under_root) {
        frappe.throw(
            __(
                "Row {0}: Warehouse {1} is outside the configured fulfillment warehouse {2}.",
                [
                    row.idx,
                    row.warehouse,
                    root.name
                ]
            )
        );
    }
}


