function setup_delivery_note_print_control(frm) {
    hide_standard_print_buttons(frm);
    remove_existing_print_dr_button(frm);
    add_custom_dr_print_button(frm);
    show_dr_print_status_message(frm);
}


function remove_existing_print_dr_button(frm) {
    try {
        frm.remove_custom_button("Print DR");
    } catch (e) {
        // Ignore if button does not exist
    }
}


function can_print_dr(frm) {
    if (!frm.doc) {
        return false;
    }

    if (frm.doc.docstatus !== 1) {
        return false;
    }

    if ((frm.doc.status || "") !== "To Bill") {
        return false;
    }

    if (!frm.doc.custom_dr_paper_serial) {
        return false;
    }

    if (cint(frm.doc.custom_dr_printed || 0) === 1) {
        return false;
    }

    if (cint(frm.doc.custom_dr_print_count || 0) > 0) {
        return false;
    }

    return true;
}


function hide_standard_print_buttons(frm) {
    if (frm.page && frm.page.wrapper) {
        frm.page.wrapper
            .find('[data-original-title="Print"]')
            .hide();

        frm.page.wrapper
            .find('[title="Print"]')
            .hide();

        frm.page.wrapper
            .find(".btn-print")
            .hide();

        frm.page.wrapper
            .find(".standard-actions .btn-print")
            .hide();
    }

    $("a, button").each(function () {
        const label = ($(this).text() || "").trim();

        if (
            label === "Print" ||
            label === "Print Preview"
        ) {
            $(this).hide();
            $(this).parent().hide();
        }
    });
}


function add_custom_dr_print_button(frm) {
    if (!can_print_dr(frm)) {
        return;
    }

    frm.add_custom_button(
        "Print DR",
        function () {
            confirm_pages_and_print_dr(frm);
        }
    ).addClass("btn-primary");
}


function confirm_pages_and_print_dr(frm) {
    if (!can_print_dr(frm)) {
        frappe.msgprint(
            "Printing is not allowed. Delivery Note must be submitted, To Bill, have a DR Starting Serial, and not yet printed."
        );

        return;
    }

    const starting_serial = cint(frm.doc.custom_dr_paper_serial || 0);

    const dialog = new frappe.ui.Dialog({
        title: "Confirm DR Papers Used",
        fields: [
            {
                fieldtype: "HTML",
                fieldname: "intro",
                options:
                    "<div style='margin-bottom: 10px;'>" +
                    "Confirm how many physical DR paper page(s) will be used for this Delivery Note." +
                    "<br><br>" +
                    "<b>Starting DR Serial:</b> " +
                    frappe.utils.escape_html(String(starting_serial)) +
                    "</div>"
            },
            {
                fieldtype: "Int",
                fieldname: "pages_used",
                label: "DR Pages / Papers Used",
                reqd: 1,
                default: 1
            },
            {
                fieldtype: "HTML",
                fieldname: "ending_serial_preview",
                options:
                    "<div id='dr-ending-serial-preview' style='margin-top: 8px; font-weight: bold;'>" +
                    "Ending DR Serial: " +
                    frappe.utils.escape_html(String(starting_serial)) +
                    "</div>"
            }
        ],
        primary_action_label: "Confirm and Print DR",
        primary_action(values) {
            const pages_used = cint(values.pages_used || 0);

            if (pages_used <= 0) {
                frappe.msgprint("DR Pages / Papers Used must be greater than zero.");
                return;
            }

            dialog.hide();

            mark_delivery_note_printed_then_open_print(
                frm,
                pages_used
            );
        }
    });

    dialog.show();

    setTimeout(function () {
        const input_field = dialog.fields_dict.pages_used;

        if (!input_field || !input_field.$input) {
            return;
        }

        input_field.$input.on("input", function () {
            const pages_used = cint(input_field.$input.val() || 0);
            let ending_serial = starting_serial;

            if (starting_serial > 0 && pages_used > 0) {
                ending_serial = starting_serial + pages_used - 1;
            }

            dialog.fields_dict.ending_serial_preview.$wrapper.html(
                "<div id='dr-ending-serial-preview' style='margin-top: 8px; font-weight: bold;'>" +
                "Ending DR Serial: " +
                frappe.utils.escape_html(String(ending_serial)) +
                "</div>"
            );
        });
    }, 300);
}


function mark_delivery_note_printed_then_open_print(frm, pages_used) {
    frappe.call({
        method: "prepare_delivery_note_print",
        args: {
            delivery_note: frm.doc.name
        },
        callback: function (prepare_response) {
            if (
                !prepare_response.message ||
                !prepare_response.message.token
            ) {
                frappe.msgprint(
                    "Failed to generate print authorization token."
                );
                return;
            }

            const token = prepare_response.message.token;

            frappe.call({
                method: "mark_delivery_note_printed",
                args: {
                    delivery_note: frm.doc.name,
                    pages_used: pages_used,
                    token: token
                },
                callback: function (mark_response) {
                    frappe.show_alert({
                        message: mark_response.message || "Delivery Note marked as printed.",
                        indicator: "green"
                    });

                    const print_format_name = "DR 2026";

                    const print_url =
                        "/printview?doctype=" +
                        encodeURIComponent("Delivery Note") +
                        "&name=" +
                        encodeURIComponent(frm.doc.name) +
                        "&format=" +
                        encodeURIComponent(print_format_name) +
                        "&no_letterhead=0" +
                        "&dr_token=" +
                        encodeURIComponent(token);

                    window.open(
                        print_url,
                        "_blank"
                    );

                    setTimeout(function () {
                        frm.reload_doc();
                    }, 1500);
                },
                error: function () {
                    frappe.msgprint(
                        "Failed to mark Delivery Note as printed. Printing was stopped."
                    );
                }
            });
        },
        error: function () {
            frappe.msgprint(
                "Failed to prepare controlled DR print. Please contact administrator."
            );
        }
    });
}


function show_dr_print_status_message(frm) {
    if (!frm.dashboard) {
        return;
    }

    if (frm.__dr_print_status_message_shown) {
        return;
    }

    let reason = "";

    if (frm.doc.docstatus !== 1) {
        reason =
            "Print DR is hidden because the Delivery Note is not submitted yet.";
    } else if ((frm.doc.status || "") !== "To Bill") {
        reason =
            "Print DR is hidden because Delivery Note status is '" +
            (frm.doc.status || "") +
            "'. It must be 'To Bill'.";
    } else if (!frm.doc.custom_dr_paper_serial) {
        reason =
            "Print DR is hidden because DR Starting Serial is missing.";
    } else if (
        cint(frm.doc.custom_dr_printed || 0) === 1 ||
        cint(frm.doc.custom_dr_print_count || 0) > 0
    ) {
        reason =
            "Print DR is hidden because this Delivery Note was already printed.";
    }

    if (reason) {
        frm.dashboard.add_comment(
            reason,
            "orange",
            true
        );

        frm.__dr_print_status_message_shown = true;
    }
}

