// ============================================================
// MAIN ACKNOWLEDGEMENT RECEIPT CONTROLLER
// ============================================================

function setup_acknowledgement_receipt_control(frm) {

    const is_customer_receipt =
        frm.doc.payment_type === 'Receive' &&
        frm.doc.party_type === 'Customer';


    // ========================================================
    // SHOW / HIDE AR FIELDS
    // ========================================================

    frm.toggle_display(
        'custom_ar_no',
        is_customer_receipt
    );

    frm.toggle_display(
        'custom_ar_status',
        is_customer_receipt
    );


    // ========================================================
    // REQUIRE AR NUMBER
    // ========================================================

    frm.toggle_reqd(
        'custom_ar_no',
        is_customer_receipt
    );


    // ========================================================
    // LOCK AR NUMBER AFTER SUBMISSION
    // ========================================================

    if (is_customer_receipt) {

        frm.set_df_property(
            'custom_ar_no',
            'read_only',
            frm.doc.docstatus !== 0
        );

    } else {

        frm.set_df_property(
            'custom_ar_no',
            'read_only',
            0
        );
    }


    // ========================================================
    // AR STATUS ALWAYS READ ONLY
    // ========================================================

    frm.set_df_property(
        'custom_ar_status',
        'read_only',
        1
    );


    // ========================================================
    // NORMALIZE EXISTING AR NUMBER
    // ========================================================

    normalize_ar_number(frm);


    // ========================================================
    // REFRESH STATUS MESSAGE
    // ========================================================

    refresh_ar_status_message(frm);
}


// ============================================================
// PRINT ACKNOWLEDGEMENT RECEIPT BUTTON
// ============================================================

function setup_acknowledgement_receipt_print_button(frm) {

    // Always remove first so refresh does not create duplicates.
    frm.remove_custom_button(
        __('Print Acknowledgement Receipt')
    );


    const is_customer_receipt =
        frm.doc.payment_type === 'Receive' &&
        frm.doc.party_type === 'Customer';


    // --------------------------------------------------------
    // BUTTON REQUIREMENTS
    //
    // 1. Customer receipt
    // 2. Submitted Payment Entry
    // 3. Physical AR number assigned
    // --------------------------------------------------------

    if (
        is_customer_receipt &&
        frm.doc.docstatus === 1 &&
        frm.doc.custom_ar_no
    ) {

        frm.add_custom_button(
            __('Print Acknowledgement Receipt'),
            function() {

                open_acknowledgement_receipt_print(frm);
            }
        );
    }
}


// ============================================================
// OPEN ACKNOWLEDGEMENT RECEIPT PRINT FORMAT
// ============================================================

function open_acknowledgement_receipt_print(frm) {

    if (!frm.doc.custom_ar_no) {

        frappe.msgprint({
            title: __('Acknowledgement Receipt'),
            indicator: 'orange',
            message:
                __('Acknowledgement Receipt No. is required before printing.')
        });

        return;
    }


    if (frm.doc.docstatus !== 1) {

        frappe.msgprint({
            title: __('Acknowledgement Receipt'),
            indicator: 'orange',
            message:
                __('The Payment Entry must be submitted before printing the Acknowledgement Receipt.')
        });

        return;
    }


    // --------------------------------------------------------
    // Tell ERPNext which Print Format should be selected.
    // --------------------------------------------------------

    frappe.route_options = {
        print_format: 'Acknowledgement Receipt'
    };


    frappe.set_route(
        'print',
        frm.doc.doctype,
        frm.doc.name
    );
}


// ============================================================
// NORMALIZE AR NUMBER
//
// AR number is deliberately stored as text.
//
// Example:
// 000125 stays 000125
// ============================================================

function normalize_ar_number(frm) {

    if (!frm.doc.custom_ar_no) {
        return;
    }


    const current_value =
        String(frm.doc.custom_ar_no);


    const cleaned_value =
        current_value.trim();


    if (cleaned_value !== current_value) {

        frm.set_value(
            'custom_ar_no',
            cleaned_value
        );
    }
}


// ============================================================
// ACKNOWLEDGEMENT RECEIPT STATUS MESSAGE
// ============================================================

function refresh_ar_status_message(frm) {

    const is_customer_receipt =
        frm.doc.payment_type === 'Receive' &&
        frm.doc.party_type === 'Customer';


    if (!is_customer_receipt) {
        return;
    }


    const ar_no =
        frm.doc.custom_ar_no || '';


    const ar_status =
        frm.doc.custom_ar_status || 'Unused';


    // ========================================================
    // DRAFT
    // ========================================================

    if (frm.doc.docstatus === 0) {

        if (!ar_no) {

            frm.dashboard.set_headline_alert(
                'Enter the physical Acknowledgement Receipt ' +
                'number before submitting this Payment Entry.',
                'orange'
            );

            return;
        }


        frm.dashboard.set_headline_alert(
            'Acknowledgement Receipt No. ' +
            '<b>' +
            frappe.utils.escape_html(ar_no) +
            '</b> is ready to be assigned.',
            'blue'
        );

        return;
    }


    // ========================================================
    // SUBMITTED
    // ========================================================

    if (frm.doc.docstatus === 1) {

        if (ar_no) {

            frm.dashboard.set_headline_alert(
                'Acknowledgement Receipt No. ' +
                '<b>' +
                frappe.utils.escape_html(ar_no) +
                '</b> is assigned to this Payment Entry.' +
                '<br>' +
                'AR Status: ' +
                '<b>' +
                frappe.utils.escape_html(ar_status) +
                '</b>',
                'green'
            );
        }

        return;
    }


    // ========================================================
    // CANCELLED
    // ========================================================

    if (frm.doc.docstatus === 2) {

        if (ar_no) {

            frm.dashboard.set_headline_alert(
                'Acknowledgement Receipt No. ' +
                '<b>' +
                frappe.utils.escape_html(ar_no) +
                '</b> has been CANCELLED and cannot be reused.',
                'red'
            );
        }
    }
}

