frappe.ui.form.on("Sales Order", {
    setup(frm) {
        setup_sales_order_queries(frm);
        setup_sales_order_fulfillment_flags(frm);
    },

    async onload(frm) {
        setup_sales_order_fulfillment_flags(frm);

        if (
            frm.is_new() &&
            !frm.doc.branch
        ) {
            await set_sales_order_branch_from_source(
                frm
            );
        }

        if (frm.doc.branch) {
            await apply_sales_order_fulfillment_settings(
                frm,
                false
            );

            update_sales_order_fulfillment_flag(
                frm
            );
        }
    },

    async refresh(frm) {
        setup_sales_order_fulfillment_flags(frm);

        if (
            frm.is_new() &&
            !frm.doc.branch
        ) {
            await set_sales_order_branch_from_source(
                frm
            );
        }

        if (frm.doc.branch) {
            await apply_sales_order_fulfillment_settings(
                frm,
                false
            );

            update_sales_order_fulfillment_flag(
                frm
            );

        } else {

            remove_sales_order_fulfillment_flag(
                frm
            );
        }

        add_sales_order_pick_list_button(
            frm
        );
    },

    async branch(frm) {
        setup_sales_order_fulfillment_flags(frm);

        frm.__branch_cost_center = "";
        frm.__selected_order_warehouse = "";
        frm.__branch_fulfillment_settings = null;

        if (!frm.doc.branch) {

            await clear_sales_order_fulfillment_values(
                frm
            );

            remove_sales_order_fulfillment_flag(
                frm
            );

            return;
        }

        await apply_sales_order_fulfillment_settings(
            frm,
            true
        );

        update_sales_order_fulfillment_flag(
            frm
        );
    },

    async custom_central_fulfillment(frm) {

        if (!frm.doc.branch) {

            frappe.msgprint(
                __(
                    "Select a Branch before changing the fulfillment mode."
                )
            );

            await frm.set_value(
                "custom_central_fulfillment",
                0
            );

            remove_sales_order_fulfillment_flag(
                frm
            );

            return;
        }

        await apply_sales_order_fulfillment_settings(
            frm,
            true
        );

        update_sales_order_fulfillment_flag(
            frm
        );
    },

    async company(frm) {

        if (!frm.doc.branch) {

            remove_sales_order_fulfillment_flag(
                frm
            );

            return;
        }

        await apply_sales_order_fulfillment_settings(
            frm,
            false
        );

        update_sales_order_fulfillment_flag(
            frm
        );
    },

    async validate(frm) {

        if (!frm.doc.branch) {

            frappe.throw(
                __("Branch is required.")
            );
        }

        if (
            !frm.doc.items ||
            !frm.doc.items.length
        ) {

            frappe.throw(
                __(
                    "Add at least one item before saving."
                )
            );
        }

        await apply_sales_order_fulfillment_settings(
            frm,
            false
        );

        validate_sales_order_item_dimensions(
            frm
        );

        update_sales_order_fulfillment_flag(
            frm
        );
    }
});


// ============================================================
// SALES ORDER ITEM EVENTS
// ============================================================

frappe.ui.form.on("Sales Order Item", {

    items_add(frm, cdt, cdn) {

        setTimeout(function () {

            apply_sales_order_item_dimensions(
                frm,
                cdt,
                cdn
            );

        }, 300);
    },

    item_code(frm, cdt, cdn) {

        apply_sales_order_item_dimensions(
            frm,
            cdt,
            cdn
        );

        setTimeout(function () {

            apply_sales_order_item_dimensions(
                frm,
                cdt,
                cdn
            );

        }, 300);

        setTimeout(function () {

            apply_sales_order_item_dimensions(
                frm,
                cdt,
                cdn
            );

        }, 800);
    },

    warehouse(frm, cdt, cdn) {

        enforce_sales_order_item_warehouse(
            frm,
            cdt,
            cdn
        );
    }
});


// ============================================================
// QUERY SETUP
// ============================================================

function setup_sales_order_queries(frm) {

    // No Branch.disabled filter.
    // Standard Branch Link permissions/search are used.

    if (
        frm.fields_dict
            .custom_fulfillment_warehouse
    ) {

        frm.set_query(
            "custom_fulfillment_warehouse",
            function () {

                const filters = {};

                if (frm.doc.company) {

                    filters.company =
                        frm.doc.company;
                }

                return {
                    filters: filters
                };
            }
        );
    }
}


// ============================================================
// INTERNAL STATE
// ============================================================

function setup_sales_order_fulfillment_flags(
    frm
) {

    if (
        frm.__loading_fulfillment ===
        undefined
    ) {

        frm.__loading_fulfillment =
            false;
    }

    if (
        frm.__branch_cost_center ===
        undefined
    ) {

        frm.__branch_cost_center =
            "";
    }

    if (
        frm.__selected_order_warehouse ===
        undefined
    ) {

        frm.__selected_order_warehouse =
            "";
    }

    if (
        frm.__branch_fulfillment_settings ===
        undefined
    ) {

        frm.__branch_fulfillment_settings =
            null;
    }
}


// ============================================================
// COPY BRANCH / MODE FROM QUOTATION OR USER
// ============================================================

async function set_sales_order_branch_from_source(
    frm
) {

    const quotation =
        get_sales_order_source_quotation(
            frm
        );

    if (quotation) {

        try {

            const quotation_response =
                await frappe.db.get_value(
                    "Quotation",
                    quotation,
                    [
                        "custom_branch",
                        "custom_central_fulfillment"
                    ]
                );

            const quotation_values =
                quotation_response &&
                quotation_response.message
                    ? quotation_response.message
                    : {};

            if (
                quotation_values.custom_branch &&
                !frm.doc.branch
            ) {

                await frm.set_value(
                    "branch",
                    quotation_values
                        .custom_branch
                );
            }

            if (
                quotation_values
                    .custom_central_fulfillment !==
                undefined
            ) {

                await frm.set_value(
                    "custom_central_fulfillment",
                    cint(
                        quotation_values
                            .custom_central_fulfillment
                    )
                );
            }

            if (frm.doc.branch) {

                return;
            }

        } catch (error) {

            console.error(
                "Unable to read source Quotation fulfillment values:",
                error
            );
        }
    }


    if (
        !frappe.session.user ||
        frappe.session.user === "Guest"
    ) {

        return;
    }


    try {

        const response =
            await frappe.call({

                method:
                    "get_current_user_default_branch"
            });

        const user_branch =
            response &&
            response.message
                ? response.message
                : "";

        if (
            user_branch &&
            !frm.doc.branch
        ) {

            await frm.set_value(
                "branch",
                user_branch
            );
        }

    } catch (error) {

        console.error(
            "Unable to retrieve default Branch:",
            error
        );
    }
}


// ============================================================
// GET SOURCE QUOTATION
// ============================================================

function get_sales_order_source_quotation(
    frm
) {

    for (
        const row of
        frm.doc.items || []
    ) {

        if (row.prevdoc_docname) {

            return row.prevdoc_docname;
        }

        if (row.quotation) {

            return row.quotation;
        }
    }

    return "";
}


// ============================================================
// APPLY SALES ORDER FULFILLMENT SETTINGS
// ============================================================

async function apply_sales_order_fulfillment_settings(
    frm,
    show_message
) {

    if (frm.__loading_fulfillment) {

        return;
    }

    if (!frm.doc.branch) {

        return;
    }

    frm.__loading_fulfillment =
        true;

    try {

        const response =
            await frappe.db.get_value(
                "Branch",
                frm.doc.branch,
                [
                    SO_BRANCH_DEFAULT_WAREHOUSE_FIELD,
                    SO_BRANCH_CENTRAL_WAREHOUSE_FIELD,
                    SO_BRANCH_COST_CENTER_FIELD,
                    SO_BRANCH_ALLOW_CENTRAL_FIELD,
                    SO_BRANCH_WAREHOUSE_COMPANY_FIELD
                ]
            );

        const settings =
            response &&
            response.message
                ? response.message
                : {};

        frm.__branch_fulfillment_settings =
            settings;

        let central_enabled =
            cint(
                frm.doc
                    .custom_central_fulfillment ||
                0
            ) === 1;


        // ====================================================
        // VALIDATE CENTRAL FULFILLMENT
        // ====================================================

        if (
            central_enabled &&
            !cint(
                settings[
                    SO_BRANCH_ALLOW_CENTRAL_FIELD
                ] || 0
            )
        ) {

            frappe.msgprint({

                title:
                    __(
                        "Central Fulfillment Not Enabled"
                    ),

                indicator:
                    "orange",

                message:
                    __(
                        "Central fulfillment is not enabled for branch {0}. Branch fulfillment will be used.",
                        [
                            frm.doc.branch
                        ]
                    )
            });

            await frm.set_value(
                "custom_central_fulfillment",
                0
            );

            central_enabled =
                false;
        }


        // ====================================================
        // DETERMINE WAREHOUSE
        // ====================================================

        let selected_warehouse =
            "";

        if (central_enabled) {

            selected_warehouse =
                settings[
                    SO_BRANCH_CENTRAL_WAREHOUSE_FIELD
                ];

        } else {

            selected_warehouse =
                settings[
                    SO_BRANCH_DEFAULT_WAREHOUSE_FIELD
                ];
        }

        if (!selected_warehouse) {

            if (central_enabled) {

                frappe.throw(
                    __(
                        "Main Fulfillment Warehouse is not configured for branch {0}.",
                        [
                            frm.doc.branch
                        ]
                    )
                );
            }

            frappe.throw(
                __(
                    "Default Branch Warehouse is not configured for branch {0}.",
                    [
                        frm.doc.branch
                    ]
                )
            );
        }


        // ====================================================
        // COST CENTER
        // ====================================================

        const branch_cost_center =
            settings[
                SO_BRANCH_COST_CENTER_FIELD
            ];

        if (!branch_cost_center) {

            frappe.throw(
                __(
                    "Selling Cost Center is not configured for branch {0}.",
                    [
                        frm.doc.branch
                    ]
                )
            );
        }


        // ====================================================
        // VALIDATIONS
        // ====================================================

        await validate_sales_order_warehouse(
            frm,
            selected_warehouse,
            central_enabled,
            settings
        );

        await validate_sales_order_cost_center(
            frm,
            branch_cost_center
        );


        // ====================================================
        // STORE ACTIVE SETTINGS
        // ====================================================

        frm.__branch_cost_center =
            branch_cost_center;

        frm.__selected_order_warehouse =
            selected_warehouse;


        // ====================================================
        // HEADER FULFILLMENT WAREHOUSE
        // ====================================================

        if (
            frm.doc
                .custom_fulfillment_warehouse !==
            selected_warehouse
        ) {

            await frm.set_value(
                "custom_fulfillment_warehouse",
                selected_warehouse
            );
        }


        // ====================================================
        // STANDARD SET WAREHOUSE
        // ====================================================

        if (
            frm.fields_dict
                .set_warehouse &&
            frm.doc.set_warehouse !==
            selected_warehouse
        ) {

            await frm.set_value(
                "set_warehouse",
                selected_warehouse
            );
        }


        // ====================================================
        // APPLY ITEM DIMENSIONS
        // ====================================================

        await set_sales_order_item_dimensions(
            frm
        );


        // ====================================================
        // USER ALERT
        // ====================================================

        if (show_message) {

            frappe.show_alert({

                message:
                    central_enabled
                        ? __(
                            "Central fulfillment applied. Warehouse: {0}. Cost Center: {1}.",
                            [
                                selected_warehouse,
                                branch_cost_center
                            ]
                        )
                        : __(
                            "Branch fulfillment applied. Warehouse: {0}. Cost Center: {1}.",
                            [
                                selected_warehouse,
                                branch_cost_center
                            ]
                        ),

                indicator:
                    central_enabled
                        ? "blue"
                        : "green"
            });
        }

    } finally {

        frm.__loading_fulfillment =
            false;
    }
}


// ============================================================
// VALIDATE SALES ORDER WAREHOUSE
// ============================================================

async function validate_sales_order_warehouse(
    frm,
    warehouse_name,
    central_enabled,
    branch_settings
) {

    const response =
        await frappe.db.get_value(
            "Warehouse",
            warehouse_name,
            [
                "name",
                "company",
                "is_group"
            ]
        );

    const warehouse =
        response &&
        response.message
            ? response.message
            : {};

    if (!warehouse.name) {

        frappe.throw(
            __(
                "Warehouse {0} could not be found.",
                [
                    warehouse_name
                ]
            )
        );
    }

    if (
        frm.doc.company &&
        warehouse.company !==
            frm.doc.company
    ) {

        frappe.throw(
            __(
                "Warehouse {0} belongs to company {1}, but this Sales Order belongs to company {2}.",
                [
                    warehouse_name,
                    warehouse.company,
                    frm.doc.company
                ]
            )
        );
    }

    const configured_company =
        branch_settings[
            SO_BRANCH_WAREHOUSE_COMPANY_FIELD
        ];

    if (
        configured_company &&
        frm.doc.company &&
        configured_company !==
            frm.doc.company
    ) {

        frappe.throw(
            __(
                "Branch {0} is configured for company {1}, but this Sales Order belongs to company {2}.",
                [
                    frm.doc.branch,
                    configured_company,
                    frm.doc.company
                ]
            )
        );
    }


    // Branch fulfillment must use an actual warehouse.
    // Central fulfillment may use a group warehouse because
    // Pick List can later determine the actual child/bin.

    if (
        !central_enabled &&
        cint(
            warehouse.is_group
        )
    ) {

        frappe.throw(
            __(
                "Default Branch Warehouse {0} is a group warehouse. Configure an actual non-group warehouse.",
                [
                    warehouse_name
                ]
            )
        );
    }
}


// ============================================================
// VALIDATE SALES ORDER COST CENTER
// ============================================================

async function validate_sales_order_cost_center(
    frm,
    cost_center
) {

    const response =
        await frappe.db.get_value(
            "Cost Center",
            cost_center,
            [
                "name",
                "company"
            ]
        );

    const values =
        response &&
        response.message
            ? response.message
            : {};

    if (!values.name) {

        frappe.throw(
            __(
                "Selling Cost Center {0} could not be found.",
                [
                    cost_center
                ]
            )
        );
    }

    if (
        frm.doc.company &&
        values.company !==
            frm.doc.company
    ) {

        frappe.throw(
            __(
                "Selling Cost Center {0} belongs to company {1}, but this Sales Order belongs to company {2}.",
                [
                    cost_center,
                    values.company,
                    frm.doc.company
                ]
            )
        );
    }
}


// ============================================================
// APPLY ITEM DIMENSIONS TO ALL ITEMS
// ============================================================

async function set_sales_order_item_dimensions(
    frm
) {

    const warehouse =
        frm.__selected_order_warehouse ||
        frm.doc
            .custom_fulfillment_warehouse;

    const cost_center =
        frm.__branch_cost_center;

    for (
        const row of
        frm.doc.items || []
    ) {

        if (
            warehouse &&
            row.warehouse !==
                warehouse
        ) {

            await frappe.model.set_value(
                row.doctype,
                row.name,
                "warehouse",
                warehouse
            );
        }

        if (
            cost_center &&
            row.cost_center !==
                cost_center
        ) {

            await frappe.model.set_value(
                row.doctype,
                row.name,
                "cost_center",
                cost_center
            );
        }
    }

    frm.refresh_field(
        "items"
    );
}


// ============================================================
// APPLY ITEM DIMENSIONS TO ONE ROW
// ============================================================

async function apply_sales_order_item_dimensions(
    frm,
    cdt,
    cdn
) {

    const row =
        locals[cdt][cdn];

    if (!row) {

        return;
    }

    const warehouse =
        frm.__selected_order_warehouse ||
        frm.doc
            .custom_fulfillment_warehouse;

    const cost_center =
        frm.__branch_cost_center;

    if (
        warehouse &&
        row.warehouse !==
            warehouse
    ) {

        await frappe.model.set_value(
            cdt,
            cdn,
            "warehouse",
            warehouse
        );
    }

    if (
        cost_center &&
        row.cost_center !==
            cost_center
    ) {

        await frappe.model.set_value(
            cdt,
            cdn,
            "cost_center",
            cost_center
        );
    }
}


// ============================================================
// PREVENT MANUAL WAREHOUSE OVERRIDE
// ============================================================

async function enforce_sales_order_item_warehouse(
    frm,
    cdt,
    cdn
) {

    if (
        frm.__loading_fulfillment
    ) {

        return;
    }

    const row =
        locals[cdt][cdn];

    if (
        !row ||
        !row.warehouse
    ) {

        return;
    }

    const expected_warehouse =
        frm.__selected_order_warehouse ||
        frm.doc
            .custom_fulfillment_warehouse;

    if (
        expected_warehouse &&
        row.warehouse !==
            expected_warehouse
    ) {

        frappe.msgprint(
            __(
                "Item warehouse must be {0}.",
                [
                    expected_warehouse
                ]
            )
        );

        await frappe.model.set_value(
            cdt,
            cdn,
            "warehouse",
            expected_warehouse
        );
    }
}


// ============================================================
// FINAL ITEM VALIDATION
// ============================================================

function validate_sales_order_item_dimensions(
    frm
) {

    if (
        !frm.doc
            .custom_fulfillment_warehouse
    ) {

        frappe.throw(
            __(
                "Order Fulfillment Warehouse is required."
            )
        );
    }

    const expected_warehouse =
        frm.__selected_order_warehouse ||
        frm.doc
            .custom_fulfillment_warehouse;

    const expected_cost_center =
        frm.__branch_cost_center;

    for (
        const row of
        frm.doc.items || []
    ) {

        if (
            expected_warehouse &&
            row.warehouse !==
                expected_warehouse
        ) {

            frappe.throw(
                __(
                    "Row {0}: Warehouse must be {1}.",
                    [
                        row.idx,
                        expected_warehouse
                    ]
                )
            );
        }

        if (
            expected_cost_center &&
            row.cost_center !==
                expected_cost_center
        ) {

            frappe.throw(
                __(
                    "Row {0}: Cost Center must be {1}.",
                    [
                        row.idx,
                        expected_cost_center
                    ]
                )
            );
        }
    }
}


// ============================================================
// CLEAR SALES ORDER FULFILLMENT VALUES
// ============================================================

async function clear_sales_order_fulfillment_values(
    frm
) {

    if (
        frm.doc
            .custom_fulfillment_warehouse
    ) {

        await frm.set_value(
            "custom_fulfillment_warehouse",
            ""
        );
    }

    if (
        frm.fields_dict
            .set_warehouse &&
        frm.doc.set_warehouse
    ) {

        await frm.set_value(
            "set_warehouse",
            ""
        );
    }

    for (
        const row of
        frm.doc.items || []
    ) {

        if (row.warehouse) {

            await frappe.model.set_value(
                row.doctype,
                row.name,
                "warehouse",
                ""
            );
        }

        if (row.cost_center) {

            await frappe.model.set_value(
                row.doctype,
                row.name,
                "cost_center",
                ""
            );
        }
    }

    frm.refresh_field(
        "items"
    );
}


// ============================================================
// PICK LIST BUTTONS
// ============================================================

function add_sales_order_pick_list_button(
    frm
) {

    // --------------------------------------------------------
    // Do not show buttons for:
    //
    // - new Sales Orders
    // - draft Sales Orders
    // - cancelled Sales Orders
    // - fully delivered Sales Orders
    // --------------------------------------------------------

    if (
        frm.is_new() ||
        frm.doc.docstatus !== 1 ||
        flt(
            frm.doc.per_delivered || 0
        ) >= 100
    ) {

        return;
    }


    // ========================================================
    // CREATE NEXT PICK LIST
    // ========================================================

    frm.add_custom_button(
        __("Create Next Pick List"),

        async function () {

            try {

                // ------------------------------------------------
                // Save any pending client-side changes first.
                // ------------------------------------------------

                if (frm.is_dirty()) {

                    await frm.save();
                }


                // ------------------------------------------------
                // Ask custom API to:
                //
                // 1. Inspect Delivered SREs
                // 2. Repair stale stock_reserved_qty
                // 3. Calculate remaining pickable qty
                // 4. Build Pick List draft data
                // ------------------------------------------------

                const prepare_response =
                    await frappe.call({

                        method:
                            "prepare_next_pick_list_for_sales_order",

                        args: {
                            sales_order:
                                frm.doc.name
                        },

                        freeze:
                            true,

                        freeze_message:
                            __(
                                "Checking remaining quantities and reservations..."
                            )
                    });


                const prepared =
                    prepare_response &&
                    prepare_response.message
                        ? prepare_response.message
                        : {};


                // ------------------------------------------------
                // API says there is nothing available to pick.
                // ------------------------------------------------

                if (!prepared.can_create) {

                    frappe.msgprint({

                        title:
                            __(
                                "Cannot Create Next Pick List"
                            ),

                        indicator:
                            "orange",

                        message:
                            prepared.message ||
                            __(
                                "No remaining quantity is available for a new Pick List."
                            )
                    });

                    return;
                }


                // ------------------------------------------------
                // Validate returned Pick List structure.
                // ------------------------------------------------

                if (
                    !prepared.pick_list_doc ||
                    !prepared.pick_list_doc.locations ||
                    !prepared.pick_list_doc.locations.length
                ) {

                    frappe.msgprint(
                        __(
                            "No pickable Sales Order rows were returned."
                        )
                    );

                    return;
                }


                // =================================================
                // CREATE DRAFT PICK LIST
                // =================================================
                //
                // We intentionally let Frappe insert the Pick List
                // normally so native Pick List before_save logic can
                // still allocate actual child/bin warehouses,
                // batches and serial numbers.
                // =================================================

                const insert_response =
                    await frappe.call({

                        method:
                            "frappe.client.insert",

                        args: {
                            doc:
                                prepared.pick_list_doc
                        },

                        freeze:
                            true,

                        freeze_message:
                            __(
                                "Creating the next Pick List..."
                            )
                    });


                const pick_list =
                    insert_response &&
                    insert_response.message
                        ? insert_response.message
                        : null;


                // ------------------------------------------------
                // Safety check.
                // ------------------------------------------------

                if (
                    !pick_list ||
                    !pick_list.name
                ) {

                    frappe.throw(
                        __(
                            "Pick List was not created."
                        )
                    );
                }


                // ------------------------------------------------
                // Success.
                // ------------------------------------------------

                frappe.show_alert({

                    message:
                        __(
                            "Pick List {0} created for the remaining quantity.",
                            [
                                pick_list.name
                            ]
                        ),

                    indicator:
                        "green"
                });


                // ------------------------------------------------
                // Open new Pick List.
                // ------------------------------------------------

                frappe.set_route(
                    "Form",
                    "Pick List",
                    pick_list.name
                );


            } catch (error) {

                console.error(
                    "Create Next Pick List failed:",
                    error
                );
            }
        },

        __("Warehouse")
    );


    // ========================================================
    // EXISTING OPEN PICK LISTS BUTTON
    // ========================================================

    frm.add_custom_button(
        __("Open Pick Lists"),

        function () {

            frappe.set_route(
                "List",
                "Pick List",
                {
                    branch:
                        frm.doc.branch
                }
            );
        },

        __("Warehouse")
    );
}


// ============================================================
// GET FULFILLMENT FLAG CONTAINER
// ============================================================

function get_sales_order_fulfillment_flag_container(
    frm
) {

    if (
        !frm ||
        !frm.page ||
        !frm.page.wrapper
    ) {

        return null;
    }

    const $page_wrapper =
        $(frm.page.wrapper);

    const $form_layout =
        $page_wrapper
            .find(
                ".form-layout"
            )
            .first();

    if (
        $form_layout.length
    ) {

        return $form_layout;
    }

    const $page_body =
        $page_wrapper
            .find(
                ".page-body"
            )
            .first();

    if (
        $page_body.length
    ) {

        return $page_body;
    }

    return $page_wrapper;
}


// ============================================================
// REMOVE FULFILLMENT FLAG
// ============================================================

function remove_sales_order_fulfillment_flag(
    frm
) {

    if (
        !frm ||
        !frm.page ||
        !frm.page.wrapper
    ) {

        return;
    }

    $(frm.page.wrapper)
        .find(
            "." +
            SO_FULFILLMENT_FLAG_CLASS
        )
        .remove();
}


// ============================================================
// UPDATE / CREATE SINGLE COLORED FULFILLMENT FLAG
// ============================================================

function update_sales_order_fulfillment_flag(
    frm
) {

    if (
        !frm.doc.branch ||
        !frm.doc
            .custom_fulfillment_warehouse
    ) {

        remove_sales_order_fulfillment_flag(
            frm
        );

        return;
    }

    const central_enabled =
        cint(
            frm.doc
                .custom_central_fulfillment ||
            0
        ) === 1;

    const branch =
        frappe.utils.escape_html(
            frm.doc.branch
        );

    const warehouse =
        frappe.utils.escape_html(
            frm.doc
                .custom_fulfillment_warehouse
        );


    // ========================================================
    // TEXT
    // ========================================================

    const title =
        central_enabled
            ? __(
                "Central Fulfillment"
            )
            : __(
                "Branch Fulfillment"
            );

    const description =
        central_enabled
            ? __(
                "The main warehouse will pick, pack, and deliver this order."
            )
            : __(
                "The selling branch warehouse will pick, pack, and deliver this order."
            );


    // ========================================================
    // COLORS
    // ========================================================

    const background_color =
        central_enabled
            ? "rgba(33, 150, 243, 0.12)"
            : "rgba(40, 167, 69, 0.12)";

    const border_color =
        central_enabled
            ? "#2196f3"
            : "#28a745";

    const title_color =
        central_enabled
            ? "#1976d2"
            : "#218838";

    const icon =
        central_enabled
            ? "🏢"
            : "🏬";


    // ========================================================
    // HTML
    // ========================================================

    const html =
        `
        <div
            class="${SO_FULFILLMENT_FLAG_CLASS}"
            data-central-fulfillment="${
                central_enabled
                    ? "1"
                    : "0"
            }"
            style="
                margin: 8px 0 12px 0;
                padding: 12px 14px;
                border: 1px solid ${border_color};
                border-left: 5px solid ${border_color};
                border-radius: 6px;
                background: ${background_color};
                line-height: 1.5;
            "
        >

            <div
                style="
                    display: flex;
                    align-items: center;
                    gap: 7px;
                    font-weight: 700;
                    font-size: 14px;
                    color: ${title_color};
                    margin-bottom: 5px;
                "
            >
                <span>
                    ${icon}
                </span>

                <span>
                    ${title}
                </span>
            </div>

            <div>
                ${__("Selling Branch")}:
                <b>${branch}</b>
            </div>

            <div>
                ${__("Physical Stock Source")}:
                <b>${warehouse}</b>
            </div>

            <div
                style="
                    margin-top: 5px;
                "
            >
                ${description}
            </div>

        </div>
        `;


    // ========================================================
    // FIND EXISTING FLAG
    // ========================================================

    const $page_wrapper =
        $(frm.page.wrapper);

    let $existing =
        $page_wrapper
            .find(
                "." +
                SO_FULFILLMENT_FLAG_CLASS
            );


    // ========================================================
    // REMOVE OLD DUPLICATES
    // ========================================================

    if (
        $existing.length > 1
    ) {

        $existing
            .slice(1)
            .remove();

        $existing =
            $page_wrapper
                .find(
                    "." +
                    SO_FULFILLMENT_FLAG_CLASS
                )
                .first();
    }


    // ========================================================
    // UPDATE EXISTING FLAG
    // ========================================================

    if (
        $existing.length
    ) {

        $existing.replaceWith(
            html
        );

        return;
    }


    // ========================================================
    // CREATE FLAG
    // ========================================================

    const $container =
        get_sales_order_fulfillment_flag_container(
            frm
        );

    if (!$container) {

        return;
    }

    if (
        $container.hasClass(
            "form-layout"
        )
    ) {

        $container.before(
            html
        );

    } else {

        $container.prepend(
            html
        );
    }
}

frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {
        load_sales_invoice_branch_data(frm);
        show_sales_invoice_branch_banner(frm);
    }
});


async function load_sales_invoice_branch_data(frm) {
    const sales_orders =
        get_invoice_sales_orders(frm);

    if (!sales_orders.length) {
        return;
    }

    const response = await frappe.db.get_value(
        "Sales Order",
        sales_orders[0],
        [
            "branch",
            "custom_fulfillment_warehouse",
            "custom_central_fulfillment"
        ]
    );

    const values =
        response && response.message
            ? response.message
            : {};

    if (!values.custom_central_fulfillment) {
        return;
    }

    if (
        values.branch &&
        frm.doc.branch !== values.branch
    ) {
        await frm.set_value(
            "branch",
            values.branch
        );
    }

    if (
        values.custom_fulfillment_warehouse &&
        frm.doc.custom_fulfillment_warehouse !==
            values.custom_fulfillment_warehouse
    ) {
        await frm.set_value(
            "custom_fulfillment_warehouse",
            values.custom_fulfillment_warehouse
        );
    }

    const branch_response =
        await frappe.db.get_value(
            "Branch",
            values.branch,
            "custom_selling_cost_center"
        );

    const cost_center =
        branch_response &&
        branch_response.message
            ? branch_response.message
                .custom_selling_cost_center
            : null;

    if (!cost_center) {
        return;
    }

    (frm.doc.items || []).forEach(
        function (row) {
            frappe.model.set_value(
                row.doctype,
                row.name,
                "cost_center",
                cost_center
            );
        }
    );

    frm.refresh_field("items");
}


function get_invoice_sales_orders(frm) {
    const sales_orders = [];

    (frm.doc.items || []).forEach(
        function (row) {
            if (
                row.sales_order &&
                !sales_orders.includes(
                    row.sales_order
                )
            ) {
                sales_orders.push(
                    row.sales_order
                );
            }
        }
    );

    return sales_orders;
}


function show_sales_invoice_branch_banner(frm) {
    if (!frm.doc.branch) {
        return;
    }

    frm.dashboard.add_comment(
        __(
            "Sales income for this invoice will be assigned to branch <b>{0}</b>.",
            [
                frappe.utils.escape_html(
                    frm.doc.branch
                )
            ]
        ),
        "green",
        true
    );
}
